/* Blackboard lessons for the plane geometry cheat sheet (one lesson per card). Texts: 'en|fr|es|ja|zh'. */
(function () {
  const R = String.raw;
  const IDEA = 'The idea|L’idée|La idea|考え方|思路', EX = 'Worked example|Exemple résolu|Ejemplo resuelto|例題|例题', YOUR = 'Your turn|À vous|Te toca|やってみよう|轮到你了';
  const TRY = 'Work it out on paper, type the answer and check it. Each hint writes the next line of the solution on the board.|Faites le calcul sur papier, tapez la réponse et vérifiez. Chaque indice écrit la ligne suivante de la solution au tableau.|Hazlo en papel, escribe la respuesta y compruébala. Cada pista escribe en la pizarra la siguiente línea de la solución.|紙で計算し、答えを入力して確かめましょう。ヒントごとに解答が 1 行ずつ黒板に書かれます。|先在纸上算，输入答案并检查。每次提示会在黑板上写出解答的下一行。';
  const F = (tex, o = {}) => ['w', R`\displaystyle ` + tex, Object.assign({ s: 26 }, o)];
  const Y = (tex, o = {}) => F(tex, Object.assign({ c: 'y' }, o));
  const W = (txt, o = {}) => ['t', txt, Object.assign({ s: 18, c: 'b' }, o)];
  const H = name => ['t', name, { head: true, s: 16, c: 'y' }];
  const P2 = (x, y) => [x, y, 0];
  const S2 = (c, r, o = {}) => ['3d', Object.assign({ flat: true, axes: false, c: [c[0], c[1], 0], r }, o)];
  const SG = (A, B, o = {}) => ['seg', A, B, o], PT = (P, lab, o = {}) => ['pt3', P, lab || '', o], LB = (P, t, o = {}) => ['lab3', P, t, o], POLY = (pts, o = {}) => ['poly3', pts, o], CI = (C, r, o = {}) => ['circ3', C, [0, 0, 1], r, o];
  // a triangle from its three sides: A(0, 0), B(c, 0), C above AB
  const tri = (a, b, c) => { const x = (b * b - a * a + c * c) / (2 * c); return [P2(0, 0), P2(c, 0), P2(x, Math.sqrt(b * b - x * x))]; };
  const drawTri = (a, b, c, o = {}) => { const [A, B, C] = tri(a, b, c), M = (p, q) => P2((p[0] + q[0]) / 2, (p[1] + q[1]) / 2);
    return [S2([c / 2, C[1] / 2], Math.max(c, C[1]) * 0.62), POLY([A, B, C], { c: 'b', fill: 0.16 }), LB(M(B, C), o.a || String(a), { c: 'y', dx: 8 }), LB(M(A, C), o.b || String(b), { c: 'y', dx: -22 }), LB(M(A, B), o.c || String(c), { c: 'y', dy: 18 })]; };
  const L = {};
  const lesson = (key, head, idea, ex, your) => {
    L[key] = [{ t: IDEA, s: idea.s, a: [H(head), ...idea.a] }, { t: EX, s: ex.s, a: [['clr'], H(head), ...ex.a] },
      { t: YOUR, s: your.s || TRY, a: [['clr'], H(head), ...(your.a || [])], ex: your.ex }];
  };

  lesson('Triangles/Heron’s formula', 'Heron’s formula|Formule de Héron|Fórmula de Herón|ヘロンの公式|海伦公式',
    { s: R`Heron gives the area of a triangle from its three sides alone — no height, no angle. First compute the semi-perimeter $s$: half of the perimeter, $s = \tfrac{a + b + c}{2}$. Then subtract each side from $s$, multiply the four numbers $s$, $s - a$, $s - b$, $s - c$, and take the square root. Each $s - a$ is positive because one side is always shorter than the other two together.|Héron donne l’aire d’un triangle à partir de ses trois côtés seulement — ni hauteur ni angle. On calcule d’abord le demi-périmètre $s$ : la moitié du périmètre, $s = \tfrac{a + b + c}{2}$. Puis on retranche chaque côté de $s$, on multiplie les quatre nombres $s$, $s - a$, $s - b$, $s - c$ et on prend la racine. Chaque $s - a$ est positif car un côté est toujours plus court que la somme des deux autres.|Herón da el área de un triángulo solo con sus tres lados, sin altura ni ángulo. Primero calcula el semiperímetro $s$: la mitad del perímetro, $s = \tfrac{a + b + c}{2}$. Luego resta cada lado a $s$, multiplica los cuatro números $s$, $s - a$, $s - b$, $s - c$ y saca la raíz. Cada $s - a$ es positivo porque un lado siempre es menor que la suma de los otros dos.|ヘロンの公式は 3 辺だけから三角形の面積を求めます（高さも角も不要）。まず半周長 $s$（周の長さの半分）$s = \tfrac{a + b + c}{2}$ を求め、$s$ から各辺を引き、$s$, $s - a$, $s - b$, $s - c$ の 4 つを掛けて平方根をとります。1 辺は他の 2 辺の和より短いので、$s - a$ などは必ず正。|海伦公式只用三边求三角形面积——不需要高或角。先算半周长 $s$：周长的一半，$s = \tfrac{a + b + c}{2}$。再用 $s$ 分别减去各边，把 $s$, $s - a$, $s - b$, $s - c$ 四个数相乘后开方。由于任意一边小于另两边之和，每个 $s - a$ 都是正数。`,
      a: [F(R`s = \frac{a + b + c}{2}`), W('s = semi-perimeter = half the perimeter|s = demi-périmètre = moitié du périmètre|s = semiperímetro = mitad del perímetro|s = 半周長 = 周の長さの半分|s = 半周长 = 周长的一半'), Y(R`S = \sqrt{s(s - a)(s - b)(s - c)}`, { s: 28 }), W('1. half the perimeter  2. subtract each side  3. multiply, square root|1. demi-périmètre  2. retrancher chaque côté  3. multiplier, racine|1. semiperímetro  2. restar cada lado  3. multiplicar, raíz|1. 半周長  2. 各辺を引く  3. 掛けて平方根|1. 半周长  2. 分别减去各边  3. 相乘开方'), ...drawTri(5, 6, 7, { a: 'a', b: 'b', c: 'c' })] },
    { s: R`Sides $5$, $6$, $7$: the perimeter is $18$, so $s = 9$. Then $s - a = 4$, $s - b = 3$, $s - c = 2$, and $S = \sqrt{9\cdot 4\cdot 3\cdot 2} = \sqrt{216} = 6\sqrt6 \approx 14.7$.|Côtés $5$, $6$, $7$ : le périmètre vaut $18$, donc $s = 9$. Alors $s - a = 4$, $s - b = 3$, $s - c = 2$ et $S = \sqrt{9\cdot 4\cdot 3\cdot 2} = \sqrt{216} = 6\sqrt6 \approx 14{,}7$.|Lados $5$, $6$, $7$: el perímetro es $18$, así que $s = 9$. Entonces $s - a = 4$, $s - b = 3$, $s - c = 2$ y $S = \sqrt{9\cdot 4\cdot 3\cdot 2} = \sqrt{216} = 6\sqrt6 \approx 14{,}7$.|3 辺 $5$, $6$, $7$：周の長さ $18$ なので $s = 9$。$s - a = 4$, $s - b = 3$, $s - c = 2$ で $S = \sqrt{9\cdot 4\cdot 3\cdot 2} = \sqrt{216} = 6\sqrt6 \approx 14.7$。|三边 $5$, $6$, $7$：周长 $18$，$s = 9$。$s - a = 4$，$s - b = 3$，$s - c = 2$，$S = \sqrt{9\cdot 4\cdot 3\cdot 2} = \sqrt{216} = 6\sqrt6 \approx 14.7$。`,
      a: [F(R`s = \frac{5 + 6 + 7}{2} = 9`), F(R`s - a = 4,\ s - b = 3,\ s - c = 2`), Y(R`S = \sqrt{9\cdot 4\cdot 3\cdot 2} = \sqrt{216} = 6\sqrt6`), ...drawTri(5, 6, 7)] },
    { a: [F(R`a = 13,\quad b = 14,\quad c = 15`), ...drawTri(13, 14, 15)],
      ex: { k: 'val', v: '84', q: R`Find the area of the triangle with sides $13$, $14$ and $15$.|Calculez l’aire du triangle de côtés $13$, $14$ et $15$.|Calcula el área del triángulo de lados $13$, $14$ y $15$.|3 辺が $13$, $14$, $15$ の三角形の面積を求めよ。|求三边为 $13$, $14$, $15$ 的三角形面积。`,
        sol: [R`s = \frac{13 + 14 + 15}{2} = 21`, R`s - a = 8,\ s - b = 7,\ s - c = 6`, R`S = \sqrt{21\cdot 8\cdot 7\cdot 6} = \sqrt{7056} = 84`] } });

  lesson('Centres and special lines/Inradius', 'Inradius|Rayon du cercle inscrit|Radio inscrito|内接円の半径|内切圆半径',
    { s: R`Join the incentre $I$ to the three vertices: the triangle splits into three triangles, each with height $r$ and one side as base. Their areas add up to $\tfrac12 r(a + b + c) = r\,s$, where $s$ is the semi-perimeter (half of the perimeter). So $S = rs$ and $r = \tfrac Ss$.|On joint le centre $I$ du cercle inscrit aux trois sommets : le triangle se découpe en trois triangles de hauteur $r$, chacun ayant un côté pour base. Leurs aires font $\tfrac12 r(a + b + c) = r\,s$, où $s$ est le demi-périmètre. Donc $S = rs$ et $r = \tfrac Ss$.|Une el incentro $I$ con los tres vértices: el triángulo se divide en tres triángulos de altura $r$, cada uno con un lado como base. Sus áreas suman $\tfrac12 r(a + b + c) = r\,s$, donde $s$ es el semiperímetro. Así $S = rs$ y $r = \tfrac Ss$.|内心 $I$ と 3 頂点を結ぶと、高さ $r$・底辺が各辺の三角形 3 つに分かれます。面積の和は $\tfrac12 r(a + b + c) = r\,s$（$s$ は半周長）。よって $S = rs$、$r = \tfrac Ss$。|把内心 $I$ 与三个顶点相连：三角形分成三个高为 $r$、底分别为三边的小三角形。面积之和为 $\tfrac12 r(a + b + c) = r\,s$（$s$ 为半周长）。所以 $S = rs$，$r = \tfrac Ss$。`,
      a: [F(R`S = \tfrac12 ra + \tfrac12 rb + \tfrac12 rc = r\,s`), Y(R`r = \frac{S}{s},\quad s = \frac{a + b + c}{2}`), S2([2, 1.5], 2.6), POLY([P2(0, 0), P2(4, 0), P2(0, 3)], { c: 'b', fill: 0.14 }), CI(P2(1, 1), 1, { c: 'y' }), PT(P2(1, 1), 'I', { c: 'y' }), SG(P2(1, 1), P2(1, 0), { c: 'g' }), LB(P2(1, 0.5), 'r', { c: 'g', dx: 6 }), SG(P2(1, 1), P2(0, 0), { c: 'chalk', dash: true }), SG(P2(1, 1), P2(4, 0), { c: 'chalk', dash: true }), SG(P2(1, 1), P2(0, 3), { c: 'chalk', dash: true })] },
    { s: R`The 3-4-5 right triangle: $S = \tfrac12\cdot 3\cdot 4 = 6$ and $s = \tfrac{3 + 4 + 5}{2} = 6$, so $r = 1$. The picture shows the circle of radius 1 touching all three sides.|Le triangle rectangle 3-4-5 : $S = \tfrac12\cdot 3\cdot 4 = 6$ et $s = \tfrac{3 + 4 + 5}{2} = 6$, donc $r = 1$. La figure montre le cercle de rayon 1 tangent aux trois côtés.|El triángulo rectángulo 3-4-5: $S = \tfrac12\cdot 3\cdot 4 = 6$ y $s = \tfrac{3 + 4 + 5}{2} = 6$, así que $r = 1$. La figura muestra la circunferencia de radio 1 tangente a los tres lados.|直角三角形 3-4-5：$S = \tfrac12\cdot 3\cdot 4 = 6$、$s = \tfrac{3 + 4 + 5}{2} = 6$ より $r = 1$。図は 3 辺に接する半径 1 の円。|直角三角形 3-4-5：$S = \tfrac12\cdot 3\cdot 4 = 6$，$s = \tfrac{3 + 4 + 5}{2} = 6$，所以 $r = 1$。图中半径为 1 的圆与三边都相切。`,
      a: [F(R`S = \tfrac12\cdot 3\cdot 4 = 6,\quad s = \frac{3 + 4 + 5}{2} = 6`), Y(R`r = \frac66 = 1`), S2([2, 1.5], 2.6), POLY([P2(0, 0), P2(4, 0), P2(0, 3)], { c: 'b', fill: 0.14 }), CI(P2(1, 1), 1, { c: 'y' }), PT(P2(1, 1), 'I', { c: 'y' }), LB(P2(2, 0), '4', { c: 'y', dy: 18 }), LB(P2(0, 1.5), '3', { c: 'y', dx: -16 }), LB(P2(2, 1.5), '5', { c: 'y', dx: 8 })] },
    { a: [F(R`a = 13,\quad b = 14,\quad c = 15`), ...drawTri(13, 14, 15)],
      ex: { k: 'val', v: '4', q: R`Find the inradius of the triangle with sides $13$, $14$, $15$ (its area is $84$).|Calculez le rayon du cercle inscrit du triangle de côtés $13$, $14$, $15$ (son aire vaut $84$).|Halla el radio inscrito del triángulo de lados $13$, $14$, $15$ (su área es $84$).|3 辺 $13$, $14$, $15$ の三角形（面積 $84$）の内接円の半径を求めよ。|求三边为 $13$, $14$, $15$ 的三角形（面积为 $84$）的内切圆半径。`,
        sol: [R`s = \frac{13 + 14 + 15}{2} = 21`, R`r = \frac{S}{s} = \frac{84}{21} = 4`] } });


  // ---------------- more helpers for the remaining cards ----------------
  const SEQ = (items, d0 = 200, step = 120) => items.map((a, i) => { const o = a[a.length - 1]; if (o && typeof o === 'object' && !Array.isArray(o)) o.d = d0 + i * step; return a; });
  const Q = (x, y) => P2(x, y);
  const ARCPTS = (cx, cy, r, a0, a1, n = 24) => [...Array(n + 1)].map((_, k) => { const t = a0 + (a1 - a0) * k / n; return Q(cx + r * Math.cos(t), cy + r * Math.sin(t)); });
  const SECTOR = (r, a0, a1, c = 'y', fill = 0.3) => POLY([Q(0, 0), ...ARCPTS(0, 0, r, a0, a1)], { c, fill });
  const SEGMT = (r, a0, a1, c = 'y', fill = 0.35) => POLY(ARCPTS(0, 0, r, a0, a1), { c, fill });
  const REG = (n, R, c = 'b', fill = 0.16, rot = Math.PI / 2) => POLY([...Array(n)].map((_, k) => Q(R * Math.cos(rot + 2 * Math.PI * k / n), R * Math.sin(rot + 2 * Math.PI * k / n))), { c, fill });
  const ON = (r, deg) => Q(r * Math.cos(deg * Math.PI / 180), r * Math.sin(deg * Math.PI / 180));
  const RT = (a, b, o = {}) => [S2([a / 2, b / 2], Math.max(a, b) * 0.62), POLY([Q(0, 0), Q(a, 0), Q(0, b)], { c: 'b', fill: 0.16 }), POLY([Q(0, 0), Q(0.12 * Math.min(a, b), 0), Q(0.12 * Math.min(a, b), 0.12 * Math.min(a, b)), Q(0, 0.12 * Math.min(a, b))], { c: 'chalk', fill: 0 }),
    LB(Q(a / 2, 0), o.a || String(a), { c: 'y', dy: 18 }), LB(Q(0, b / 2), o.b || String(b), { c: 'y', dx: -22 }), LB(Q(a / 2, b / 2), o.c || '', { c: 'y', dx: 10, dy: -8 })];
  const TRYD = 'Work it out on paper, type the answer (a number, or an exact value such as 2sqrt(3) or 5pi/12) and check it.|Faites le calcul sur papier, tapez la réponse (un nombre, ou une valeur exacte comme 2sqrt(3) ou 5pi/12) et vérifiez.|Hazlo en papel, escribe la respuesta (un número o un valor exacto como 2sqrt(3) o 5pi/12) y compruébala.|紙で計算し、答え（数、または 2sqrt(3)、5pi/12 のような正確な値）を入力して確かめよう。|在纸上算出，输入答案（数字，或 2sqrt(3)、5pi/12 这样的精确值）并检查。';
  const SEC4 = () => [LB(Q(0.45, 0.25), 'A', { c: 'y' }), LB(Q(3.45, 0.25), 'B', { c: 'p' }), LB(Q(1.5, 2.55), 'C', { c: 'chalk' }), LB(Q(5, 0.4), 'A + B', { c: 'o' })];
  const BIS = () => { const [A, B, C] = tri(10, 9, 6), D = P2(B[0] + 0.4 * (C[0] - B[0]), B[1] + 0.4 * (C[1] - B[1]));
    return [S2([C[0] / 2 + 1.5, C[1] / 2], 5.2), ...SEQ([POLY([A, B, C], { c: 'b', fill: 0.14 }), SG(A, D, { c: 'y' }), PT(D, 'D', { c: 'o' }), LB(A, 'A', { c: 'chalk', dx: -14 }), LB(B, 'B', { c: 'chalk', dx: 10 }), LB(C, 'C', { c: 'chalk', dy: -12 }), LB(P2(3, -0.6), '6', { c: 'y' }), LB(P2(C[0] / 2 - 0.8, C[1] / 2), '9', { c: 'y' })])]; };
  const G = (key, head, idea, ex, your) => lesson(key, head, idea, ex, Object.assign({ s: TRYD }, your));

  // =============================== Triangles ===============================
  G('Triangles/Angle sum', 'Angle sum of a triangle|Somme des angles d’un triangle|Suma de los ángulos de un triángulo|三角形の内角の和|三角形内角和',
    { s: R`Draw the line through one vertex parallel to the opposite side: the three angles of the triangle reappear along that line as alternate angles, and together they make a straight angle, $180°$.|Tracez par un sommet la parallèle au côté opposé : les trois angles du triangle s’y retrouvent comme angles alternes-internes et forment un angle plat, $180°$.|Traza por un vértice la paralela al lado opuesto: los tres ángulos del triángulo reaparecen sobre ella como alternos internos y juntos forman un ángulo llano, $180°$.|1 つの頂点を通り対辺に平行な直線を引くと、3 つの角が錯角としてその直線上に並び、合わせて平角 $180°$。|过一个顶点作对边的平行线：三角形的三个角作为内错角出现在这条线上，合起来是平角 $180°$。`,
      a: [Y(R`A + B + C = 180^\circ`, { s: 30 }), S2([3, 1.5], 3.4), ...SEQ([POLY([Q(0, 0), Q(6, 0), Q(2, 3)], { c: 'b', fill: 0.16 }), SG(Q(-0.5, 3), Q(5, 3), { c: 'g' }), LB(Q(0.6, 0.25), 'A', { c: 'y' }), LB(Q(5.2, 0.25), 'B', { c: 'p' }), LB(Q(2, 2.55), 'C', { c: 'o' }), LB(Q(1.1, 3.25), 'A', { c: 'y' }), LB(Q(3.1, 3.25), 'B', { c: 'p' })])] },
    { s: R`$A = 50°$, $B = 60°$: $C = 180° - 110° = 70°$.|$A = 50°$, $B = 60°$ : $C = 70°$.|$A = 50°$, $B = 60°$: $C = 70°$.|$C = 70°$。|$C = 70°$。`,
      a: [Y(R`C = 180^\circ - 50^\circ - 60^\circ = 70^\circ`)] },
    { a: [F(R`\text{isosceles, apex angle } 40^\circ`)],
      ex: { k: 'val', v: '70', q: R`An isosceles triangle has apex angle $40°$. Find each base angle in degrees.|Un triangle isocèle a un angle au sommet de $40°$. Trouvez chaque angle à la base (en degrés).|Un triángulo isósceles tiene ángulo desigual de $40°$. Halla cada ángulo de la base en grados.|頂角 $40°$ の二等辺三角形の底角（度）を求めよ。|顶角为 $40°$ 的等腰三角形，求底角（度）。`, sol: [R`2x + 40 = 180`, R`x = 70^\circ`] } });

  G('Triangles/Area', 'Area of a triangle|Aire d’un triangle|Área de un triángulo|三角形の面積|三角形面积',
    { s: R`Half of base times height: the triangle is half of the rectangle around it. If you know two sides and the angle between them, the height on side $a$ is $b\sin C$, which gives $\tfrac12 ab\sin C$.|La moitié de base × hauteur : le triangle est la moitié du rectangle qui l’entoure. Avec deux côtés et l’angle compris, la hauteur sur $a$ vaut $b\sin C$, d’où $\tfrac12 ab\sin C$.|La mitad de base por altura: el triángulo es la mitad del rectángulo que lo rodea. Con dos lados y el ángulo comprendido, la altura sobre $a$ es $b\sin C$, de ahí $\tfrac12 ab\sin C$.|底辺 × 高さ ÷ 2（外側の長方形の半分）。2 辺とその間の角がわかれば、高さは $b\sin C$ なので $\tfrac12 ab\sin C$。|底乘高的一半：三角形是外接矩形的一半。已知两边及夹角时，边 $a$ 上的高为 $b\sin C$，故 $\tfrac12 ab\sin C$。`,
      a: [Y(R`S = \tfrac12\,c\,h = \tfrac12\,ab\sin C`), S2([4, 2.5], 4.2), ...SEQ([POLY([Q(0, 0), Q(8, 0), Q(3, 5)], { c: 'b', fill: 0.18 }), SG(Q(3, 0), Q(3, 5), { c: 'p', dash: true }), POLY([Q(0, 0), Q(8, 0), Q(8, 5), Q(0, 5)], { c: 'chalk', fill: 0 }), LB(Q(4, -0.5), 'c = 8', { c: 'y' }), LB(Q(3.6, 2.5), 'h = 5', { c: 'p' })])] },
    { s: R`Base 8 and height 5: $S = 20$. Sides 6 and 8 with $30°$ between them: $S = \tfrac12\cdot 6\cdot 8\cdot\tfrac12 = 12$.|Base 8, hauteur 5 : $S = 20$. Côtés 6 et 8 avec $30°$ entre eux : $S = 12$.|Base 8 y altura 5: $S = 20$. Lados 6 y 8 con $30°$ entre ellos: $S = 12$.|$S = 20$、$S = 12$。|$S = 20$，$S = 12$。`,
      a: [F(R`\tfrac12\cdot 8\cdot 5 = 20`), Y(R`\tfrac12\cdot 6\cdot 8\cdot\sin 30^\circ = 12`)] },
    { a: [F(R`a = 5,\quad b = 6,\quad C = 60^\circ`)],
      ex: { k: 'val', v: '15sqrt(3)/2', q: R`Find the area of a triangle with $a = 5$, $b = 6$ and $C = 60°$.|Calculez l’aire d’un triangle avec $a = 5$, $b = 6$ et $C = 60°$.|Halla el área de un triángulo con $a = 5$, $b = 6$ y $C = 60°$.|$a = 5$, $b = 6$, $C = 60°$ の三角形の面積を求めよ。|求 $a = 5$，$b = 6$，$C = 60°$ 的三角形面积。`, sol: [R`\tfrac12\cdot 5\cdot 6\cdot\frac{\sqrt3}{2}`, R`= \frac{15\sqrt3}{2} \approx 12.99`] } });

  G('Triangles/Triangle inequality', 'The triangle inequality|L’inégalité triangulaire|La desigualdad triangular|三角不等式|三角不等式',
    { s: R`The straight path is the shortest, so each side is shorter than the other two together. With three lengths, check only that the longest is less than the sum of the other two. For a missing side: $\lvert a - b\rvert < c < a + b$.|Le chemin direct est le plus court : chaque côté est plus petit que la somme des deux autres. Avec trois longueurs, il suffit de vérifier que la plus grande est inférieure à la somme des deux autres. Pour un côté inconnu : $\lvert a - b\rvert < c < a + b$.|El camino recto es el más corto, así que cada lado es menor que la suma de los otros dos. Con tres longitudes basta comprobar que la mayor sea menor que la suma de las otras. Para un lado desconocido: $\lvert a - b\rvert < c < a + b$.|まっすぐが最短なので、どの辺も他の 2 辺の和より短い。3 つの長さなら最長辺だけ確かめればよい。未知の辺は $\lvert a - b\rvert < c < a + b$。|直线最短，所以每条边小于另两边之和。给定三条长度只需检查最长边小于另两边之和。未知边：$\lvert a - b\rvert < c < a + b$。`,
      a: [Y(R`\lvert a - b\rvert < c < a + b`, { s: 30 }), S2([4, 1.6], 4.4), ...SEQ([SG(Q(0, 0), Q(8, 0), { c: 'y' }), SG(Q(0, 0), Q(1.5, 2.598), { c: 'b' }), SG(Q(8, 0), Q(6, 3.464), { c: 'p' }), LB(Q(0.4, 1.5), '3', { c: 'b' }), LB(Q(7.4, 1.9), '4', { c: 'p' }), LB(Q(4, -0.5), '8', { c: 'y' }), LB(Q(3.8, 3.1), '?', { c: 'o' })])] },
    { s: R`Sticks 3, 4 and 8: $3 + 4 = 7 < 8$, so they cannot close up (the picture). Sticks 3, 4, 6: $3 + 4 > 6$, so they form a triangle.|Bâtons 3, 4 et 8 : $3 + 4 < 8$, impossible (la figure). 3, 4, 6 : $3 + 4 > 6$, possible.|Palos 3, 4 y 8: $3 + 4 < 8$, imposible (la figura). 3, 4, 6: $3 + 4 > 6$, posible.|3, 4, 8 は不可、3, 4, 6 は可。|3、4、8 不行；3、4、6 可以。`,
      a: [F(R`3 + 4 = 7 < 8\ \times`), Y(R`3 + 4 = 7 > 6\ \checkmark`)] },
    { a: [F(R`a = 5,\quad b = 9,\quad c\ \text{integer}`)],
      ex: { k: 'val', v: '9', q: R`Two sides are 5 and 9. How many integer values can the third side take?|Deux côtés mesurent 5 et 9. Combien de valeurs entières peut prendre le troisième ?|Dos lados miden 5 y 9. ¿Cuántos valores enteros puede tomar el tercero?|2 辺が 5 と 9。3 辺目がとりうる整数値は何通りか。|两边为 5 和 9，第三边可取多少个整数值？`, sol: [R`4 < c < 14`, R`c = 5, \dots, 13:\ 9`] } });

  G('Triangles/Exterior angle', 'The exterior angle|L’angle extérieur|El ángulo exterior|外角|外角',
    { s: R`Extend one side: the exterior angle and the interior angle $C$ make $180°$, and so do $A + B + C$. So the exterior angle equals the sum of the two remote interior angles.|Prolongez un côté : l’angle extérieur et l’angle $C$ font $180°$, comme $A + B + C$. L’angle extérieur vaut donc la somme des deux angles intérieurs non adjacents.|Prolonga un lado: el ángulo exterior y el interior $C$ suman $180°$, igual que $A + B + C$. Así el exterior es la suma de los dos interiores no adyacentes.|辺を延長すると外角と $C$ の和は $180°$、$A + B + C$ も $180°$。よって外角は隣り合わない 2 つの内角の和。|延长一边：外角与内角 $C$ 之和为 $180°$，$A + B + C$ 也是。所以外角等于两个不相邻内角之和。`,
      a: [Y(R`180^\circ - C = A + B`, { s: 30 }), S2([3.5, 1.5], 3.6), ...SEQ([POLY([Q(0, 0), Q(4, 0), Q(1.5, 3)], { c: 'b', fill: 0.16 }), SG(Q(4, 0), Q(7, 0), { c: 'chalk', dash: true }), ...SEC4()])] },
    { s: R`$A = 45°$ and $B = 65°$: the exterior angle at $C$ is $110°$ — no need to find $C = 70°$ first.|$A = 45°$, $B = 65°$ : l’angle extérieur en $C$ vaut $110°$.|$A = 45°$, $B = 65°$: el ángulo exterior en $C$ es $110°$.|外角は $110°$。|外角为 $110°$。`,
      a: [Y(R`45^\circ + 65^\circ = 110^\circ`)] },
    { a: [F(R`\text{exterior } 130^\circ,\quad A = 55^\circ`)],
      ex: { k: 'val', v: '75', q: R`An exterior angle of a triangle is $130°$ and one remote interior angle is $55°$. Find the other remote interior angle.|Un angle extérieur vaut $130°$ et un angle intérieur non adjacent $55°$. Trouvez l’autre.|Un ángulo exterior mide $130°$ y un interior no adyacente $55°$. Halla el otro.|外角 $130°$、隣り合わない内角の一方が $55°$。もう一方は？|外角 $130°$，一个不相邻内角 $55°$，求另一个。`, sol: [R`55 + x = 130`, R`x = 75^\circ`] } });

  G('Triangles/Largest side', 'Largest side, largest angle|Plus grand côté, plus grand angle|Lado mayor, ángulo mayor|大きい辺と大きい角|大边对大角',
    { s: R`In a triangle the longer side faces the larger angle, and vice versa: open the angle wider and the opposite side stretches. So to order the sides, order the angles.|Dans un triangle, le plus grand côté est face au plus grand angle, et réciproquement : ouvrir l’angle allonge le côté opposé. Pour ranger les côtés, on range les angles.|En un triángulo el lado mayor está frente al ángulo mayor, y al revés: al abrir el ángulo se alarga el lado opuesto. Para ordenar los lados, ordena los ángulos.|三角形では大きい辺の向かいに大きい角がある（逆も）。角を開くと対辺が伸びる。辺の大小は角の大小で決まる。|三角形中大边对大角，反之亦然：角张开，对边就变长。所以给边排序就给角排序。`,
      a: [Y(R`a > b \iff A > B`, { s: 30 }), ...drawTri(7, 5, 6)] },
    { s: R`Sides $a = 7$, $b = 5$, $c = 6$: the largest angle is $A$ (opposite 7), the smallest is $B$ (opposite 5).|Côtés $7$, $5$, $6$ : le plus grand angle est $A$ (face à 7), le plus petit $B$.|Lados $7$, $5$, $6$: el ángulo mayor es $A$ (frente a 7) y el menor $B$.|最大角は $A$。|最大角为 $A$。`,
      a: [Y(R`7 > 6 > 5 \Rightarrow A > C > B`)] },
    { a: [F(R`A = 50^\circ,\quad B = 70^\circ`)],
      ex: { k: 'val', v: '70', q: R`A triangle has $A = 50°$ and $B = 70°$. What is the angle opposite its longest side, in degrees?|Un triangle a $A = 50°$ et $B = 70°$. Quel est l’angle opposé à son plus grand côté (en degrés) ?|Un triángulo tiene $A = 50°$ y $B = 70°$. ¿Cuánto mide el ángulo opuesto a su lado mayor?|$A = 50°$, $B = 70°$ の三角形で最長辺の対角（度）は？|三角形 $A = 50°$，$B = 70°$，最长边所对的角是多少度？`, sol: [R`C = 60^\circ`, R`\text{largest angle } B = 70^\circ`] } });

  // =============================== Right triangles ===============================
  G('Right triangles/Pythagoras', 'Pythagoras’ theorem|Théorème de Pythagore|Teorema de Pitágoras|三平方の定理|勾股定理',
    { s: R`In a right triangle, the square on the hypotenuse has the same area as the squares on the two legs together. Use it to find a missing side, and backwards: if $a^2 + b^2 = c^2$, the angle opposite $c$ is right.|Dans un triangle rectangle, le carré construit sur l’hypoténuse a la même aire que les carrés des deux côtés de l’angle droit réunis. On l’utilise pour trouver un côté, et à l’envers : si $a^2 + b^2 = c^2$, l’angle opposé à $c$ est droit.|En un triángulo rectángulo, el cuadrado sobre la hipotenusa tiene la misma área que los de los dos catetos juntos. Sirve para hallar un lado y, al revés, si $a^2 + b^2 = c^2$ el ángulo opuesto a $c$ es recto.|直角三角形では斜辺上の正方形の面積は 2 つの脚の正方形の和。辺を求めるのに使い、逆に $a^2 + b^2 = c^2$ なら $c$ の対角は直角。|直角三角形中，斜边上的正方形面积等于两直角边上正方形面积之和。可求边长；反之若 $a^2 + b^2 = c^2$，$c$ 所对的角是直角。`,
      a: [Y(R`a^2 + b^2 = c^2`, { s: 30 }), S2([2, 1.5], 4.2), ...SEQ([POLY([Q(0, 0), Q(4, 0), Q(0, 3)], { c: 'chalk', fill: 0.1 }), POLY([Q(0, 0), Q(4, 0), Q(4, -4), Q(0, -4)], { c: 'b', fill: 0.25 }), POLY([Q(0, 0), Q(0, 3), Q(-3, 3), Q(-3, 0)], { c: 'p', fill: 0.25 }), POLY([Q(4, 0), Q(0, 3), Q(3, 7), Q(7, 4)], { c: 'y', fill: 0.25 }), LB(Q(2, -2), '16', { c: 'b' }), LB(Q(-1.5, 1.5), '9', { c: 'p' }), LB(Q(3.5, 3.5), '25', { c: 'y' })])] },
    { s: R`Legs 6 and 8: $c = \sqrt{36 + 64} = 10$.|Côtés 6 et 8 : $c = \sqrt{100} = 10$.|Catetos 6 y 8: $c = \sqrt{100} = 10$.|$c = 10$。|$c = 10$。`,
      a: [Y(R`c = \sqrt{6^2 + 8^2} = 10`), ...RT(8, 6, { c: '10' })] },
    { a: [F(R`c = 13,\quad a = 5`), ...RT(5, 12, { b: '?', c: '13' })],
      ex: { k: 'val', v: '12', q: R`A right triangle has hypotenuse 13 and one leg 5. Find the other leg.|Un triangle rectangle a une hypoténuse de 13 et un côté de 5. Trouvez l’autre côté.|Un triángulo rectángulo tiene hipotenusa 13 y un cateto 5. Halla el otro cateto.|斜辺 13、1 辺 5 の直角三角形の残りの辺を求めよ。|直角三角形斜边 13，一条直角边 5，求另一条。`, sol: [R`b^2 = 169 - 25 = 144`, R`b = 12`] } });

  const ALT = [S2([5, 2.4], 5.6), ...SEQ([POLY([Q(0, 0), Q(10, 0), Q(3.6, 4.8)], { c: 'b', fill: 0.16 }), SG(Q(3.6, 4.8), Q(3.6, 0), { c: 'p', dash: true }), LB(Q(1.8, -0.5), 'p = 3.6', { c: 'y' }), LB(Q(6.8, -0.5), 'q = 6.4', { c: 'y' }), LB(Q(4.4, 2.2), 'h', { c: 'p' }), LB(Q(1.4, 2.8), '6', { c: 'chalk' }), LB(Q(7.2, 2.8), '8', { c: 'chalk' })])];
  G('Right triangles/Altitude to the hypotenuse', 'The altitude to the hypotenuse|La hauteur relative à l’hypoténuse|La altura sobre la hipotenusa|斜辺への垂線|斜边上的高',
    { s: R`The area can be written with the legs ($\tfrac12 ab$) or with the hypotenuse and its altitude ($\tfrac12 ch$), so $h = \tfrac{ab}{c}$. The altitude splits the triangle into two triangles similar to it, which gives $h^2 = pq$ with $p$, $q$ the pieces of the hypotenuse.|L’aire s’écrit avec les côtés de l’angle droit ($\tfrac12 ab$) ou avec l’hypoténuse et sa hauteur ($\tfrac12 ch$) : $h = \tfrac{ab}{c}$. La hauteur coupe le triangle en deux triangles semblables à lui, d’où $h^2 = pq$, $p$ et $q$ étant les morceaux de l’hypoténuse.|El área se escribe con los catetos ($\tfrac12 ab$) o con la hipotenusa y su altura ($\tfrac12 ch$), así que $h = \tfrac{ab}{c}$. La altura divide el triángulo en dos semejantes a él, lo que da $h^2 = pq$ con $p$, $q$ los trozos de la hipotenusa.|面積は $\tfrac12 ab$ とも $\tfrac12 ch$ とも書けるので $h = \tfrac{ab}{c}$。垂線で元と相似な 2 つの三角形に分かれ、斜辺の 2 つの部分 $p$, $q$ について $h^2 = pq$。|面积可写成 $\tfrac12 ab$ 或 $\tfrac12 ch$，所以 $h = \tfrac{ab}{c}$。高把三角形分成两个与原三角形相似的三角形，得 $h^2 = pq$（$p$、$q$ 为斜边被分成的两段）。`,
      a: [Y(R`h = \frac{ab}{c},\qquad h^2 = p\,q`), ...ALT] },
    { s: R`Legs 6 and 8, hypotenuse 10: $h = \tfrac{48}{10} = 4.8$. The pieces are $p = 3.6$ and $q = 6.4$, and indeed $3.6\cdot 6.4 = 23.04 = 4.8^2$.|Côtés 6 et 8, hypoténuse 10 : $h = 4{,}8$ ; $p = 3{,}6$, $q = 6{,}4$ et $3{,}6\cdot 6{,}4 = 23{,}04 = 4{,}8^2$.|Catetos 6 y 8, hipotenusa 10: $h = 4{,}8$; $p = 3{,}6$, $q = 6{,}4$ y $3{,}6\cdot 6{,}4 = 23{,}04 = 4{,}8^2$.|$h = 4.8$、$pq = 23.04$。|$h = 4.8$，$pq = 23.04$。`,
      a: [F(R`h = \frac{6\cdot 8}{10} = 4.8`), Y(R`p\,q = 3.6\cdot 6.4 = 23.04 = h^2`), ...ALT] },
    { a: [F(R`a = 9,\quad b = 12`)],
      ex: { k: 'val', v: '7.2', q: R`A right triangle has legs 9 and 12. Find the altitude to the hypotenuse.|Un triangle rectangle a des côtés de l’angle droit 9 et 12. Calculez la hauteur relative à l’hypoténuse.|Un triángulo rectángulo tiene catetos 9 y 12. Halla la altura sobre la hipotenusa.|脚が 9 と 12 の直角三角形の斜辺への垂線の長さを求めよ。|直角边为 9 和 12，求斜边上的高。`, sol: [R`c = 15`, R`h = \frac{9\cdot 12}{15} = 7.2`] } });

  G('Right triangles/Legs and projections', 'Legs and their projections|Côtés et projections|Catetos y proyecciones|脚とその射影|直角边与射影',
    { s: R`Each leg is the mean proportional between the hypotenuse and its own projection on it (Euclid’s leg theorem). It comes from the same similar triangles: $\tfrac{a}{c} = \tfrac{p}{a}$.|Chaque côté de l’angle droit est moyenne proportionnelle entre l’hypoténuse et sa projection sur elle. Cela vient des mêmes triangles semblables : $\tfrac{a}{c} = \tfrac{p}{a}$.|Cada cateto es media proporcional entre la hipotenusa y su proyección sobre ella (teorema del cateto). Sale de los mismos triángulos semejantes: $\tfrac{a}{c} = \tfrac{p}{a}$.|各脚は斜辺とその射影の比例中項（ユークリッドの定理）。同じ相似から $\tfrac{a}{c} = \tfrac{p}{a}$。|每条直角边是斜边与其在斜边上射影的比例中项（射影定理）。来自同样的相似：$\tfrac{a}{c} = \tfrac{p}{a}$。`,
      a: [Y(R`a^2 = c\,p,\qquad b^2 = c\,q`), ...ALT] },
    { s: R`Hypotenuse 10, leg 6: its projection is $p = \tfrac{36}{10} = 3.6$; the other leg’s projection is $10 - 3.6 = 6.4$, and $8^2 = 10\cdot 6.4$.|Hypoténuse 10, côté 6 : $p = 3{,}6$ ; l’autre projection vaut $6{,}4$ et $8^2 = 10\cdot 6{,}4$.|Hipotenusa 10, cateto 6: $p = 3{,}6$; la otra proyección es $6{,}4$ y $8^2 = 10\cdot 6{,}4$.|$p = 3.6$。|$p = 3.6$。`,
      a: [Y(R`p = \frac{6^2}{10} = 3.6,\quad q = 6.4`)] },
    { a: [F(R`c = 25,\quad a = 15`)],
      ex: { k: 'val', v: '9', q: R`The hypotenuse is 25 and one leg is 15. Find the projection of that leg on the hypotenuse.|L’hypoténuse vaut 25 et un côté 15. Trouvez la projection de ce côté sur l’hypoténuse.|La hipotenusa mide 25 y un cateto 15. Halla la proyección de ese cateto sobre la hipotenusa.|斜辺 25、脚 15。この脚の斜辺への射影を求めよ。|斜边 25，一条直角边 15，求它在斜边上的射影。`, sol: [R`p = \frac{15^2}{25}`, R`= 9`] } });

  G('Right triangles/Median to the hypotenuse', 'The median to the hypotenuse|La médiane relative à l’hypoténuse|La mediana sobre la hipotenusa|斜辺の中線|斜边上的中线',
    { s: R`A right triangle is half of a rectangle; its hypotenuse is a diagonal, and the diagonals of a rectangle bisect each other and are equal. So the midpoint of the hypotenuse is equally far from all three vertices — the circumcentre — and $m_c = \tfrac c2$.|Un triangle rectangle est la moitié d’un rectangle ; l’hypoténuse en est une diagonale, et les diagonales d’un rectangle se coupent en leur milieu et sont égales. Le milieu de l’hypoténuse est donc à égale distance des trois sommets — c’est le centre du cercle circonscrit — et $m_c = \tfrac c2$.|Un triángulo rectángulo es medio rectángulo; la hipotenusa es una diagonal, y las diagonales de un rectángulo se cortan en su punto medio y son iguales. El punto medio de la hipotenusa equidista de los tres vértices (es el circuncentro) y $m_c = \tfrac c2$.|直角三角形は長方形の半分で、斜辺は対角線。長方形の対角線は等しく互いに二等分するので、斜辺の中点は 3 頂点から等距離（外心）で $m_c = \tfrac c2$。|直角三角形是矩形的一半，斜边是对角线；矩形对角线相等且互相平分。所以斜边中点到三个顶点等距——是外心——$m_c = \tfrac c2$。`,
      a: [Y(R`m_c = \frac c2`, { s: 30 }), S2([4, 3], 5), ...SEQ([POLY([Q(0, 0), Q(8, 0), Q(0, 6)], { c: 'b', fill: 0.16 }), POLY([Q(8, 0), Q(8, 6), Q(0, 6)], { c: 'chalk', fill: 0 }), SG(Q(0, 0), Q(4, 3), { c: 'y' }), CI(Q(4, 3), 5, { c: 'p', fill: 0 }), PT(Q(4, 3), 'M', { c: 'o' })])] },
    { s: R`Legs 6 and 8, hypotenuse 10: the median from the right angle is 5, and the circle through the three vertices has the hypotenuse as diameter.|Côtés 6 et 8, hypoténuse 10 : la médiane issue de l’angle droit vaut 5.|Catetos 6 y 8, hipotenusa 10: la mediana desde el ángulo recto mide 5.|中線は 5。|中线为 5。`,
      a: [Y(R`m_c = \frac{10}{2} = 5`)] },
    { a: [F(R`a = 5,\quad b = 12`)],
      ex: { k: 'val', v: '6.5', q: R`A right triangle has legs 5 and 12. Find the median to the hypotenuse.|Un triangle rectangle a des côtés de l’angle droit 5 et 12. Calculez la médiane relative à l’hypoténuse.|Un triángulo rectángulo tiene catetos 5 y 12. Halla la mediana sobre la hipotenusa.|脚が 5 と 12 の直角三角形の斜辺の中線を求めよ。|直角边 5 和 12，求斜边上的中线。`, sol: [R`c = 13`, R`m_c = 6.5`] } });

  G('Right triangles/Special triangles', 'The special right triangles|Les triangles rectangles remarquables|Los triángulos rectángulos notables|特別な直角三角形|特殊直角三角形',
    { s: R`Half an equilateral triangle is a $30°$–$60°$–$90°$ triangle with sides $1 : \sqrt3 : 2$; half a square is a $45°$–$45°$–$90°$ triangle with sides $1 : 1 : \sqrt2$. They give the exact values of sin, cos and tan at $30°$, $45°$, $60°$.|La moitié d’un triangle équilatéral est un triangle $30°$–$60°$–$90°$ de côtés $1 : \sqrt3 : 2$ ; la moitié d’un carré est un triangle $45°$–$45°$–$90°$ de côtés $1 : 1 : \sqrt2$. Ils donnent les valeurs exactes de sin, cos, tan en $30°$, $45°$, $60°$.|La mitad de un equilátero es un triángulo $30°$–$60°$–$90°$ de lados $1 : \sqrt3 : 2$; la mitad de un cuadrado es un $45°$–$45°$–$90°$ de lados $1 : 1 : \sqrt2$. Dan los valores exactos de sen, cos y tan en $30°$, $45°$, $60°$.|正三角形の半分は $30°$–$60°$–$90°$（$1 : \sqrt3 : 2$）、正方形の半分は $45°$–$45°$–$90°$（$1 : 1 : \sqrt2$）。$30°$, $45°$, $60°$ の三角比の正確な値を与える。|等边三角形的一半是 $30°$–$60°$–$90°$ 三角形，边比 $1 : \sqrt3 : 2$；正方形的一半是 $45°$–$45°$–$90°$，边比 $1 : 1 : \sqrt2$。它们给出 $30°$、$45°$、$60°$ 的三角函数精确值。`,
      a: [Y(R`1 : \sqrt3 : 2\qquad 1 : 1 : \sqrt2`, { s: 30 }), S2([2.2, 0.9], 2.6), ...SEQ([POLY([Q(0, 0), Q(1.732, 0), Q(0, 1)], { c: 'b', fill: 0.2 }), LB(Q(0.87, -0.25), '√3', { c: 'y' }), LB(Q(-0.2, 0.5), '1', { c: 'y' }), LB(Q(1, 0.7), '2', { c: 'y' }), POLY([Q(2.8, 0), Q(4.3, 0), Q(2.8, 1.5)], { c: 'p', fill: 0.2 }), LB(Q(3.55, -0.25), '1', { c: 'y' }), LB(Q(2.6, 0.75), '1', { c: 'y' }), LB(Q(3.8, 0.95), '√2', { c: 'y' })])] },
    { s: R`A $30°$–$60°$–$90°$ triangle with hypotenuse 10: the short leg (opposite $30°$) is 5, the long leg $5\sqrt3 \approx 8.66$.|Hypoténuse 10 : petit côté 5, grand côté $5\sqrt3$.|Hipotenusa 10: cateto corto 5, cateto largo $5\sqrt3$.|短い脚 5、長い脚 $5\sqrt3$。|短边 5，长边 $5\sqrt3$。`,
      a: [Y(R`10 = 2\cdot 5 \Rightarrow 5,\ 5\sqrt3`)] },
    { a: [F(R`45^\circ\!-\!45^\circ\!-\!90^\circ,\quad \text{leg } 7`)],
      ex: { k: 'val', v: '7sqrt(2)', q: R`An isosceles right triangle has legs 7. Find its hypotenuse.|Un triangle rectangle isocèle a des côtés de 7. Trouvez son hypoténuse.|Un triángulo rectángulo isósceles tiene catetos 7. Halla su hipotenusa.|等辺 7 の直角二等辺三角形の斜辺を求めよ。|等腰直角三角形直角边为 7，求斜边。`, sol: [R`7 : 7 : 7\sqrt2`, R`7\sqrt2 \approx 9.90`] } });

  G('Right triangles/Pythagorean triples', 'Pythagorean triples|Triplets pythagoriciens|Ternas pitagóricas|ピタゴラス数|勾股数',
    { s: R`Whole-number right triangles. Multiples of a triple are triples ($6, 8, 10$), and every primitive triple comes from two numbers $m > n$: $(m^2 - n^2,\ 2mn,\ m^2 + n^2)$. Recognising them saves square roots.|Triangles rectangles à côtés entiers. Les multiples d’un triplet en sont aussi ($6, 8, 10$), et tout triplet primitif s’obtient avec deux nombres $m > n$ : $(m^2 - n^2,\ 2mn,\ m^2 + n^2)$. Les reconnaître évite des racines.|Triángulos rectángulos de lados enteros. Los múltiplos de una terna son ternas ($6, 8, 10$), y toda terna primitiva sale de dos números $m > n$: $(m^2 - n^2,\ 2mn,\ m^2 + n^2)$. Reconocerlas ahorra raíces.|辺が整数の直角三角形。倍数もピタゴラス数（$6, 8, 10$）で、原始的なものは $m > n$ から $(m^2 - n^2,\ 2mn,\ m^2 + n^2)$。見分けると平方根の計算が省ける。|边长为整数的直角三角形。倍数也是勾股数（$6, 8, 10$），所有本原勾股数由 $m > n$ 给出：$(m^2 - n^2,\ 2mn,\ m^2 + n^2)$。认出它们可省去开方。`,
      a: [Y(R`(m^2 - n^2,\ 2mn,\ m^2 + n^2)`, { s: 28 }), F(R`(3, 4, 5),\ (5, 12, 13),\ (8, 15, 17),\ (7, 24, 25)`, { s: 22 })] },
    { s: R`$m = 4$, $n = 1$: $(15, 8, 17)$; check $225 + 64 = 289 = 17^2$.|$m = 4$, $n = 1$ : $(15, 8, 17)$ ; $225 + 64 = 289$.|$m = 4$, $n = 1$: $(15, 8, 17)$; $225 + 64 = 289$.|$(15, 8, 17)$。|$(15, 8, 17)$。`,
      a: [Y(R`m = 4,\ n = 1:\ (15,\ 8,\ 17)`), ...RT(15, 8, { c: '17' })] },
    { a: [F(R`m = 5,\quad n = 2`)],
      ex: { k: 'val', v: '29', q: R`Use $m = 5$, $n = 2$ to build a Pythagorean triple. What is its hypotenuse?|Avec $m = 5$, $n = 2$, construisez un triplet pythagoricien. Quelle est son hypoténuse ?|Con $m = 5$, $n = 2$ construye una terna pitagórica. ¿Cuál es su hipotenusa?|$m = 5$, $n = 2$ でピタゴラス数を作る。斜辺は？|用 $m = 5$，$n = 2$ 构造勾股数，斜边是多少？`, sol: [R`(25 - 4,\ 20,\ 25 + 4) = (21, 20, 29)`, R`29`] } });

  // =============================== Centres and special lines ===============================
  G('Centres and special lines/Circumradius', 'The circumradius|Le rayon du cercle circonscrit|El radio de la circunferencia circunscrita|外接円の半径|外接圆半径',
    { s: R`The circle through the three vertices has its centre where the perpendicular bisectors meet. Its radius follows from the extended law of sines, $\tfrac{a}{\sin A} = 2R$, or from the area, $R = \tfrac{abc}{4S}$.|Le cercle passant par les trois sommets a pour centre l’intersection des médiatrices. Son rayon découle de la loi des sinus étendue, $\tfrac{a}{\sin A} = 2R$, ou de l’aire, $R = \tfrac{abc}{4S}$.|La circunferencia que pasa por los tres vértices tiene el centro donde se cortan las mediatrices. Su radio sale del teorema del seno extendido, $\tfrac{a}{\sin A} = 2R$, o del área, $R = \tfrac{abc}{4S}$.|3 頂点を通る円の中心は垂直二等分線の交点。半径は拡張正弦定理 $\tfrac{a}{\sin A} = 2R$、または面積から $R = \tfrac{abc}{4S}$。|过三顶点的圆，圆心在垂直平分线交点。半径由扩展正弦定理 $\tfrac{a}{\sin A} = 2R$ 或面积 $R = \tfrac{abc}{4S}$ 得到。`,
      a: [Y(R`R = \frac{abc}{4S} = \frac{a}{2\sin A}`), S2([2, 1.5], 2.8), ...SEQ([POLY([Q(0, 0), Q(4, 0), Q(0, 3)], { c: 'b', fill: 0.16 }), CI(Q(2, 1.5), 2.5, { c: 'y', fill: 0 }), PT(Q(2, 1.5), 'O', { c: 'o' })])] },
    { s: R`For 3-4-5: $R = \tfrac{60}{4\cdot 6} = 2.5$ — half the hypotenuse, as expected. For 13-14-15 ($S = 84$): $R = \tfrac{2730}{336} = 8.125$.|Pour 3-4-5 : $R = 2{,}5$. Pour 13-14-15 ($S = 84$) : $R = 8{,}125$.|Para 3-4-5: $R = 2{,}5$. Para 13-14-15 ($S = 84$): $R = 8{,}125$.|$R = 2.5$、$R = 8.125$。|$R = 2.5$，$R = 8.125$。`,
      a: [F(R`R = \frac{3\cdot 4\cdot 5}{4\cdot 6} = 2.5`), Y(R`R = \frac{13\cdot 14\cdot 15}{4\cdot 84} = 8.125`)] },
    { a: [F(R`\text{equilateral, side } 6`)],
      ex: { k: 'val', v: '2sqrt(3)', q: R`Find the circumradius of an equilateral triangle with side 6.|Calculez le rayon du cercle circonscrit d’un triangle équilatéral de côté 6.|Halla el radio circunscrito de un triángulo equilátero de lado 6.|1 辺 6 の正三角形の外接円の半径を求めよ。|边长 6 的等边三角形外接圆半径是多少？`, sol: [R`R = \frac{6}{2\sin 60^\circ} = \frac{6}{\sqrt3}`, R`= 2\sqrt3 \approx 3.46`] } });

  G('Centres and special lines/Median length', 'Length of a median|Longueur d’une médiane|Longitud de una mediana|中線の長さ|中线长',
    { s: R`The median from $A$ goes to the midpoint of $a$. Apollonius: $b^2 + c^2 = 2m_a^2 + \tfrac{a^2}{2}$ (the parallelogram law, since doubling the median gives a parallelogram with sides $b$, $c$ and diagonals $a$, $2m_a$). Solve for $m_a$.|La médiane issue de $A$ va au milieu de $a$. Apollonius : $b^2 + c^2 = 2m_a^2 + \tfrac{a^2}{2}$ (loi du parallélogramme : en doublant la médiane on obtient un parallélogramme de côtés $b$, $c$ et de diagonales $a$, $2m_a$).|La mediana desde $A$ va al punto medio de $a$. Apolonio: $b^2 + c^2 = 2m_a^2 + \tfrac{a^2}{2}$ (ley del paralelogramo: duplicando la mediana sale un paralelogramo de lados $b$, $c$ y diagonales $a$, $2m_a$).|$A$ からの中線は $a$ の中点へ。中線定理：$b^2 + c^2 = 2m_a^2 + \tfrac{a^2}{2}$（中線を 2 倍すると辺 $b$, $c$、対角線 $a$, $2m_a$ の平行四辺形）。|从 $A$ 出发的中线到 $a$ 的中点。阿波罗尼奥斯定理：$b^2 + c^2 = 2m_a^2 + \tfrac{a^2}{2}$（中线加倍得边为 $b$、$c$、对角线为 $a$、$2m_a$ 的平行四边形）。`,
      a: [Y(R`m_a = \tfrac12\sqrt{2b^2 + 2c^2 - a^2}`, { s: 28 })] },
    { s: R`Sides 7, 8, 9, median to the side 8: $\tfrac12\sqrt{2\cdot 49 + 2\cdot 81 - 64} = \tfrac12\sqrt{196} = 7$.|Côtés 7, 8, 9, médiane vers le côté 8 : $\tfrac12\sqrt{196} = 7$.|Lados 7, 8, 9, mediana al lado 8: $\tfrac12\sqrt{196} = 7$.|中線は 7。|中线为 7。`,
      a: [Y(R`\tfrac12\sqrt{98 + 162 - 64} = \tfrac12\sqrt{196} = 7`)] },
    { a: [F(R`a = 6,\quad b = c = 5`), ...drawTri(6, 5, 5)],
      ex: { k: 'val', v: '4', q: R`In a triangle with $a = 6$ and $b = c = 5$, find the median $m_a$.|Dans un triangle avec $a = 6$ et $b = c = 5$, calculez la médiane $m_a$.|En un triángulo con $a = 6$ y $b = c = 5$, halla la mediana $m_a$.|$a = 6$, $b = c = 5$ の三角形の中線 $m_a$ を求めよ。|三角形 $a = 6$，$b = c = 5$，求中线 $m_a$。`, sol: [R`\tfrac12\sqrt{50 + 50 - 36} = \tfrac12\cdot 8`, R`= 4`] } });

  const MED = [S2([3, 2], 3.6), ...SEQ([POLY([Q(0, 0), Q(6, 0), Q(2, 5)], { c: 'b', fill: 0.14 }), SG(Q(2, 5), Q(3, 0), { c: 'y' }), SG(Q(0, 0), Q(4, 2.5), { c: 'chalk', dash: true }), SG(Q(6, 0), Q(1, 2.5), { c: 'chalk', dash: true }), PT(Q(8 / 3, 5 / 3), 'G', { c: 'o' }), PT(Q(3, 0), 'M', { c: 'y' }), LB(Q(2, 5.35), 'A', { c: 'chalk' })])];
  G('Centres and special lines/Centroid', 'The centroid divides the medians 2 : 1|Le centre de gravité partage les médianes 2 : 1|El baricentro divide las medianas 2 : 1|重心は中線を 2 : 1 に分ける|重心分中线为 2 : 1',
    { s: R`The three medians meet at one point $G$, two thirds of the way from each vertex to the midpoint of the opposite side. So $AG$ is twice $GM$, and $AG = \tfrac23$ of the median.|Les trois médianes se coupent en $G$, aux deux tiers du chemin entre chaque sommet et le milieu du côté opposé. Donc $AG = 2\,GM$, et $AG = \tfrac23$ de la médiane.|Las tres medianas se cortan en $G$, a dos tercios del camino de cada vértice al punto medio del lado opuesto. Así $AG = 2\,GM$ y $AG = \tfrac23$ de la mediana.|3 本の中線は $G$ で交わり、各頂点から対辺の中点まで $\tfrac23$ の位置。$AG = 2\,GM$。|三条中线交于 $G$，位于每个顶点到对边中点的三分之二处。所以 $AG = 2\,GM$，$AG$ 是中线的 $\tfrac23$。`,
      a: [Y(R`AG : GM = 2 : 1`, { s: 30 }), ...MED] },
    { s: R`A median of length 9 is cut by $G$ into $AG = 6$ and $GM = 3$.|Une médiane de longueur 9 est coupée en $AG = 6$ et $GM = 3$.|Una mediana de 9 queda dividida en $AG = 6$ y $GM = 3$.|$AG = 6$、$GM = 3$。|$AG = 6$，$GM = 3$。`,
      a: [Y(R`AG = \tfrac23\cdot 9 = 6,\quad GM = 3`)] },
    { a: [F(R`m = 12`), ...MED],
      ex: { k: 'val', v: '4', q: R`A median has length 12. Find $GM$, the distance from the centroid to the midpoint of the side.|Une médiane mesure 12. Calculez $GM$, la distance du centre de gravité au milieu du côté.|Una mediana mide 12. Halla $GM$, la distancia del baricentro al punto medio del lado.|中線の長さが 12。重心から辺の中点までの距離 $GM$ を求めよ。|中线长 12，求重心到边中点的距离 $GM$。`, sol: [R`GM = \tfrac13\cdot 12`, R`= 4`] } });

  G('Centres and special lines/Angle bisector theorem', 'The angle bisector theorem|Le théorème de la bissectrice|El teorema de la bisectriz|角の二等分線の定理|角平分线定理',
    { s: R`The bisector of angle $A$ cuts the opposite side in the same ratio as the two adjacent sides. The two small triangles have the same height from $A$, and their areas are also $\tfrac12\cdot AB\cdot AD\sin\tfrac A2$ and $\tfrac12\cdot AC\cdot AD\sin\tfrac A2$.|La bissectrice de l’angle $A$ coupe le côté opposé dans le rapport des deux côtés adjacents. Les deux petits triangles ont la même hauteur issue de $A$, et leurs aires valent aussi $\tfrac12\cdot AB\cdot AD\sin\tfrac A2$ et $\tfrac12\cdot AC\cdot AD\sin\tfrac A2$.|La bisectriz del ángulo $A$ corta el lado opuesto en la misma razón que los dos lados adyacentes. Los dos triángulos pequeños tienen la misma altura desde $A$, y sus áreas son también $\tfrac12\cdot AB\cdot AD\sin\tfrac A2$ y $\tfrac12\cdot AC\cdot AD\sin\tfrac A2$.|角 $A$ の二等分線は対辺を隣の 2 辺の比に分ける。2 つの小三角形は $A$ からの高さが同じで、面積は $\tfrac12\cdot AB\cdot AD\sin\tfrac A2$ と $\tfrac12\cdot AC\cdot AD\sin\tfrac A2$ とも書ける。|角 $A$ 的平分线把对边分成与两邻边相同的比。两个小三角形从 $A$ 出发的高相同，面积又可写成 $\tfrac12\cdot AB\cdot AD\sin\tfrac A2$ 和 $\tfrac12\cdot AC\cdot AD\sin\tfrac A2$。`,
      a: [Y(R`\frac{BD}{DC} = \frac{AB}{AC}`, { s: 30 }), ...BIS()] },
    { s: R`$AB = 6$, $AC = 9$, $BC = 10$: the bisector from $A$ splits $BC$ in the ratio $2 : 3$, so $BD = 4$ and $DC = 6$.|$AB = 6$, $AC = 9$, $BC = 10$ : rapport $2 : 3$, donc $BD = 4$, $DC = 6$.|$AB = 6$, $AC = 9$, $BC = 10$: razón $2 : 3$, así que $BD = 4$ y $DC = 6$.|$BD = 4$、$DC = 6$。|$BD = 4$，$DC = 6$。`,
      a: [F(R`BD : DC = 6 : 9 = 2 : 3`), Y(R`BD = \tfrac25\cdot 10 = 4,\quad DC = 6`)] },
    { a: [F(R`AB = 5,\quad AC = 7,\quad BC = 8`)],
      ex: { k: 'val', v: '10/3', q: R`$AB = 5$, $AC = 7$, $BC = 8$. The bisector from $A$ meets $BC$ at $D$. Find $BD$.|$AB = 5$, $AC = 7$, $BC = 8$. La bissectrice issue de $A$ coupe $BC$ en $D$. Calculez $BD$.|$AB = 5$, $AC = 7$, $BC = 8$. La bisectriz desde $A$ corta $BC$ en $D$. Halla $BD$.|$AB = 5$, $AC = 7$, $BC = 8$。$A$ からの二等分線と $BC$ の交点 $D$ について $BD$ を求めよ。|$AB = 5$，$AC = 7$，$BC = 8$，$A$ 的平分线交 $BC$ 于 $D$，求 $BD$。`, sol: [R`BD : DC = 5 : 7`, R`BD = \tfrac{5}{12}\cdot 8 = \tfrac{10}{3}`] } });

  G('Centres and special lines/Similar triangles', 'Similar figures|Figures semblables|Figuras semejantes|相似な図形|相似图形',
    { s: R`If every length is multiplied by $k$, areas are multiplied by $k^2$ (two directions) and volumes by $k^3$ (three directions). Angles do not change. Doubling a model makes it four times the paint and eight times the weight.|Si toutes les longueurs sont multipliées par $k$, les aires le sont par $k^2$ (deux directions) et les volumes par $k^3$ (trois directions). Les angles ne changent pas. Doubler une maquette demande quatre fois plus de peinture et pèse huit fois plus.|Si todas las longitudes se multiplican por $k$, las áreas se multiplican por $k^2$ (dos direcciones) y los volúmenes por $k^3$ (tres). Los ángulos no cambian. Duplicar una maqueta pide cuatro veces la pintura y pesa ocho veces más.|長さが $k$ 倍なら面積は $k^2$ 倍（2 方向）、体積は $k^3$ 倍（3 方向）。角は変わらない。模型を 2 倍にすると塗料は 4 倍、重さは 8 倍。|所有长度乘 $k$，面积乘 $k^2$（两个方向），体积乘 $k^3$（三个方向）。角不变。模型放大 2 倍，油漆 4 倍，重量 8 倍。`,
      a: [Y(R`L' = kL,\quad S' = k^2 S,\quad V' = k^3 V`, { s: 26 }), S2([3, 1.5], 3.6), ...SEQ([POLY([Q(0, 0), Q(2, 0), Q(0.6, 1.4)], { c: 'b', fill: 0.25 }), POLY([Q(2.6, 0), Q(6.6, 0), Q(3.8, 2.8)], { c: 'y', fill: 0.2 }), LB(Q(1, -0.3), '2', { c: 'b' }), LB(Q(4.6, -0.3), '4', { c: 'y' })])] },
    { s: R`Scale factor $k = 3$: a triangle of area 5 becomes area $45$; a box of volume 2 becomes volume $54$.|Rapport $k = 3$ : une aire de 5 devient $45$ ; un volume de 2 devient $54$.|Razón $k = 3$: un área de 5 pasa a $45$; un volumen de 2 pasa a $54$.|面積 45、体積 54。|面积 45，体积 54。`,
      a: [Y(R`k = 3:\ 5 \to 45,\quad 2 \to 54`)] },
    { a: [F(R`\text{ratio } 2 : 5,\quad S_{\text{small}} = 12`)],
      ex: { k: 'val', v: '75', q: R`Two similar triangles have sides in the ratio $2 : 5$. The small one has area 12. Find the area of the large one.|Deux triangles semblables ont des côtés dans le rapport $2 : 5$. Le petit a une aire de 12. Calculez l’aire du grand.|Dos triángulos semejantes tienen lados en razón $2 : 5$. El pequeño tiene área 12. Halla el área del grande.|相似比 $2 : 5$ の 2 つの三角形で小さい方の面積が 12。大きい方の面積は？|两个相似三角形边长比 $2 : 5$，小的面积 12，求大的面积。`, sol: [R`k = \tfrac52,\quad k^2 = \tfrac{25}{4}`, R`12\cdot\tfrac{25}{4} = 75`] } });

  // =============================== Circles ===============================
  G('Circles/Circumference and area', 'Circumference and area of a circle|Périmètre et aire d’un disque|Longitud y área del círculo|円周と面積|圆的周长与面积',
    { s: R`$\pi$ is the ratio of circumference to diameter, so $C = 2\pi r$. Cut the disc into thin sectors and lay them alternately: they form almost a rectangle of width $\pi r$ (half the circumference) and height $r$, so $S = \pi r^2$.|$\pi$ est le rapport du périmètre au diamètre : $C = 2\pi r$. En découpant le disque en secteurs fins posés tête-bêche, on obtient presque un rectangle de largeur $\pi r$ et de hauteur $r$ : $S = \pi r^2$.|$\pi$ es la razón entre longitud y diámetro, así que $C = 2\pi r$. Cortando el círculo en sectores finos y colocándolos alternados se forma casi un rectángulo de base $\pi r$ y altura $r$: $S = \pi r^2$.|$\pi$ は円周 ÷ 直径なので $C = 2\pi r$。円を細い扇形に切って交互に並べると幅 $\pi r$、高さ $r$ のほぼ長方形になり $S = \pi r^2$。|$\pi$ 是周长与直径之比，所以 $C = 2\pi r$。把圆切成细扇形交错排列，几乎成为宽 $\pi r$、高 $r$ 的矩形：$S = \pi r^2$。`,
      a: [Y(R`C = 2\pi r,\qquad S = \pi r^2`, { s: 30 }), S2([0, 0], 2), ...SEQ([...Array(8)].map((_, k) => SECTOR(1.6, k * Math.PI / 4, (k + 1) * Math.PI / 4, k % 2 ? 'b' : 'y', 0.3)), 200, 120)] },
    { s: R`$r = 3$: $C = 6\pi \approx 18.85$ and $S = 9\pi \approx 28.27$.|$r = 3$ : $C = 6\pi$, $S = 9\pi$.|$r = 3$: $C = 6\pi$, $S = 9\pi$.|$6\pi$、$9\pi$。|$6\pi$，$9\pi$。`,
      a: [Y(R`C = 6\pi,\quad S = 9\pi`)] },
    { a: [F(R`C = 10\pi`)],
      ex: { k: 'val', v: '25pi', q: R`A circle has circumference $10\pi$. Find its area.|Un cercle a un périmètre de $10\pi$. Calculez l’aire du disque.|Una circunferencia mide $10\pi$. Halla el área del círculo.|円周が $10\pi$ の円の面積を求めよ。|圆周长为 $10\pi$，求面积。`, sol: [R`2\pi r = 10\pi \Rightarrow r = 5`, R`S = 25\pi`] } });

  const SEC = (deg, c = 'y') => [S2([0, 0.6], 2.3), CI(Q(0, 0), 2, { c: 'b', fill: 0.05 }), SECTOR(2, 0, deg * Math.PI / 180, c, 0.3), SG(Q(0, 0), Q(2, 0), { c: 'chalk' }), SG(Q(0, 0), ON(2, deg), { c: 'chalk' }), LB(ON(0.55, deg / 2), 'θ', { c: 'o' })];
  G('Circles/Arc length', 'Arc length|Longueur d’un arc|Longitud de un arco|弧の長さ|弧长',
    { s: R`An angle of one radian cuts off an arc as long as the radius — that is the definition of the radian. So an angle of $\theta$ radians cuts off $\theta$ radii: $s = r\theta$. In degrees: $s = \tfrac{\alpha}{360}\cdot 2\pi r$.|Un angle d’un radian intercepte un arc de longueur égale au rayon — c’est la définition du radian. Un angle de $\theta$ radians intercepte donc $\theta$ rayons : $s = r\theta$. En degrés : $s = \tfrac{\alpha}{360}\cdot 2\pi r$.|Un ángulo de un radián abarca un arco tan largo como el radio: esa es la definición de radián. Así un ángulo de $\theta$ radianes abarca $\theta$ radios: $s = r\theta$. En grados: $s = \tfrac{\alpha}{360}\cdot 2\pi r$.|1 ラジアンは半径と同じ長さの弧を切り取る角（定義）。$\theta$ ラジアンなら弧は半径 $\theta$ 個分：$s = r\theta$。度なら $s = \tfrac{\alpha}{360}\cdot 2\pi r$。|1 弧度的角截得与半径等长的弧——这是弧度的定义。所以 $\theta$ 弧度截得 $\theta$ 个半径长：$s = r\theta$。用度数：$s = \tfrac{\alpha}{360}\cdot 2\pi r$。`,
      a: [Y(R`s = r\theta\quad (\theta\ \text{in radians})`, { s: 28 }), ...SEC(68.75)] },
    { s: R`$r = 5$, $\theta = 1.2$ rad: $s = 6$.|$r = 5$, $\theta = 1{,}2$ rad : $s = 6$.|$r = 5$, $\theta = 1{,}2$ rad: $s = 6$.|$s = 6$。|$s = 6$。`,
      a: [Y(R`s = 5\cdot 1.2 = 6`)] },
    { a: [F(R`r = 6,\quad \alpha = 60^\circ`), ...SEC(60)],
      ex: { k: 'val', v: '2pi', q: R`Find the length of an arc of a circle of radius 6 cut off by a central angle of $60°$.|Calculez la longueur de l’arc d’un cercle de rayon 6 intercepté par un angle au centre de $60°$.|Halla la longitud del arco de una circunferencia de radio 6 abarcado por un ángulo central de $60°$.|半径 6、中心角 $60°$ の弧の長さを求めよ。|半径 6、圆心角 $60°$ 所对的弧长是多少？`, sol: [R`60^\circ = \frac\pi3`, R`s = 6\cdot\frac\pi3 = 2\pi`] } });

  G('Circles/Sector area', 'Area of a sector|Aire d’un secteur|Área de un sector|扇形の面積|扇形面积',
    { s: R`A sector is the fraction $\tfrac{\theta}{2\pi}$ of the disc: $\tfrac{\theta}{2\pi}\cdot\pi r^2 = \tfrac12 r^2\theta$. Since $s = r\theta$, this is also $\tfrac12 rs$ — like a triangle with base $s$ and height $r$.|Un secteur est la fraction $\tfrac{\theta}{2\pi}$ du disque : $\tfrac12 r^2\theta$. Comme $s = r\theta$, c’est aussi $\tfrac12 rs$ — comme un triangle de base $s$ et de hauteur $r$.|Un sector es la fracción $\tfrac{\theta}{2\pi}$ del círculo: $\tfrac12 r^2\theta$. Como $s = r\theta$, también es $\tfrac12 rs$, como un triángulo de base $s$ y altura $r$.|扇形は円の $\tfrac{\theta}{2\pi}$ なので $\tfrac12 r^2\theta$。$s = r\theta$ より $\tfrac12 rs$（底辺 $s$、高さ $r$ の三角形のよう）。|扇形是圆的 $\tfrac{\theta}{2\pi}$：$\tfrac12 r^2\theta$。因 $s = r\theta$，也等于 $\tfrac12 rs$——像底为 $s$、高为 $r$ 的三角形。`,
      a: [Y(R`S = \tfrac12 r^2\theta = \tfrac12 r s`, { s: 30 }), ...SEC(60)] },
    { s: R`$r = 4$, $\theta = \tfrac\pi3$: $S = \tfrac12\cdot 16\cdot\tfrac\pi3 = \tfrac{8\pi}{3} \approx 8.38$.|$r = 4$, $\theta = \tfrac\pi3$ : $S = \tfrac{8\pi}{3}$.|$r = 4$, $\theta = \tfrac\pi3$: $S = \tfrac{8\pi}{3}$.|$\tfrac{8\pi}{3}$。|$\tfrac{8\pi}{3}$。`,
      a: [Y(R`S = \tfrac12\cdot 4^2\cdot\frac\pi3 = \frac{8\pi}{3}`)] },
    { a: [F(R`r = 10,\quad s = 5`)],
      ex: { k: 'val', v: '25', q: R`A sector of a circle of radius 10 has arc length 5. Find its area.|Un secteur d’un cercle de rayon 10 a un arc de longueur 5. Calculez son aire.|Un sector de una circunferencia de radio 10 tiene arco 5. Halla su área.|半径 10、弧の長さ 5 の扇形の面積を求めよ。|半径 10、弧长 5 的扇形面积是多少？`, sol: [R`S = \tfrac12\cdot 10\cdot 5`, R`= 25`] } });

  G('Circles/Degrees and radians', 'Degrees and radians|Degrés et radians|Grados y radianes|度とラジアン|角度与弧度',
    { s: R`A full turn is $360°$ or $2\pi$ radians, so $180° = \pi$. To convert degrees to radians multiply by $\tfrac{\pi}{180}$; the other way, by $\tfrac{180}{\pi}$. One radian is about $57.3°$.|Un tour complet vaut $360°$ ou $2\pi$ radians, donc $180° = \pi$. Pour passer des degrés aux radians on multiplie par $\tfrac{\pi}{180}$ ; dans l’autre sens par $\tfrac{180}{\pi}$. Un radian vaut environ $57{,}3°$.|Una vuelta completa son $360°$ o $2\pi$ radianes, así que $180° = \pi$. De grados a radianes se multiplica por $\tfrac{\pi}{180}$; al revés, por $\tfrac{180}{\pi}$. Un radián son unos $57{,}3°$.|1 回転は $360°$ ＝ $2\pi$ ラジアンなので $180° = \pi$。度→ラジアンは $\tfrac{\pi}{180}$ 倍、逆は $\tfrac{180}{\pi}$ 倍。1 ラジアンは約 $57.3°$。|一周是 $360°$ 即 $2\pi$ 弧度，所以 $180° = \pi$。度化弧度乘 $\tfrac{\pi}{180}$，反之乘 $\tfrac{180}{\pi}$。1 弧度约 $57.3°$。`,
      a: [Y(R`180^\circ = \pi,\qquad \theta = \frac{\pi\,\alpha^\circ}{180}`, { s: 28 }), ...SEC(57.3)] },
    { s: R`$135° = \tfrac{135\pi}{180} = \tfrac{3\pi}{4}$, and $2$ rad $= \tfrac{360°}{\pi} \approx 114.6°$.|$135° = \tfrac{3\pi}{4}$ ; $2$ rad $\approx 114{,}6°$.|$135° = \tfrac{3\pi}{4}$; $2$ rad $\approx 114{,}6°$.|$\tfrac{3\pi}{4}$、$114.6°$。|$\tfrac{3\pi}{4}$，$114.6°$。`,
      a: [F(R`135^\circ = \frac{3\pi}{4}`), Y(R`2\ \text{rad} = \frac{360^\circ}{\pi} \approx 114.6^\circ`)] },
    { a: [F(R`75^\circ`)],
      ex: { k: 'val', v: '5pi/12', q: R`Convert $75°$ to radians.|Convertissez $75°$ en radians.|Pasa $75°$ a radianes.|$75°$ をラジアンに直せ。|把 $75°$ 化为弧度。`, sol: [R`75\cdot\frac{\pi}{180}`, R`= \frac{5\pi}{12}`] } });

  G('Circles/Chord', 'Length of a chord|Longueur d’une corde|Longitud de una cuerda|弦の長さ|弦长',
    { s: R`The radius perpendicular to a chord bisects it and bisects the central angle. Each half-chord is the side opposite $\tfrac\theta2$ in a right triangle with hypotenuse $r$: $\tfrac{AB}{2} = r\sin\tfrac\theta2$.|Le rayon perpendiculaire à une corde la coupe en son milieu et coupe l’angle au centre en deux. Chaque demi-corde est le côté opposé à $\tfrac\theta2$ dans un triangle rectangle d’hypoténuse $r$ : $\tfrac{AB}{2} = r\sin\tfrac\theta2$.|El radio perpendicular a una cuerda la divide por la mitad y divide el ángulo central. Cada media cuerda es el cateto opuesto a $\tfrac\theta2$ en un triángulo rectángulo de hipotenusa $r$: $\tfrac{AB}{2} = r\sin\tfrac\theta2$.|弦に垂直な半径は弦と中心角を二等分する。半分の弦は斜辺 $r$ の直角三角形で $\tfrac\theta2$ の対辺：$\tfrac{AB}{2} = r\sin\tfrac\theta2$。|垂直于弦的半径平分弦和圆心角。半弦是斜边为 $r$ 的直角三角形中 $\tfrac\theta2$ 的对边：$\tfrac{AB}{2} = r\sin\tfrac\theta2$。`,
      a: [Y(R`AB = 2r\sin\frac\theta2`, { s: 30 }), S2([0, 0.4], 2.4), CI(Q(0, 0), 2, { c: 'b', fill: 0.05 }), ...SEQ([SG(ON(2, 30), ON(2, 150), { c: 'y' }), SG(Q(0, 0), ON(2, 30), { c: 'chalk' }), SG(Q(0, 0), ON(2, 150), { c: 'chalk' }), SG(Q(0, 0), Q(0, 1), { c: 'p', dash: true }), LB(ON(2.3, 30), 'B', { c: 'chalk' }), LB(ON(2.3, 150), 'A', { c: 'chalk' })])] },
    { s: R`$r = 10$, $\theta = 60°$: $AB = 2\cdot 10\cdot\sin 30° = 10$ — the chord equals the radius (an equilateral triangle).|$r = 10$, $\theta = 60°$ : $AB = 10$ — triangle équilatéral.|$r = 10$, $\theta = 60°$: $AB = 10$, triángulo equilátero.|$AB = 10$。|$AB = 10$。`,
      a: [Y(R`AB = 20\sin 30^\circ = 10`)] },
    { a: [F(R`r = 8,\quad \theta = 90^\circ`)],
      ex: { k: 'val', v: '8sqrt(2)', q: R`Find the chord of a circle of radius 8 subtending a central angle of $90°$.|Calculez la corde d’un cercle de rayon 8 interceptant un angle au centre de $90°$.|Halla la cuerda de una circunferencia de radio 8 con ángulo central de $90°$.|半径 8、中心角 $90°$ の弦の長さを求めよ。|半径 8、圆心角 $90°$ 所对的弦长是多少？`, sol: [R`2\cdot 8\sin 45^\circ`, R`= 8\sqrt2 \approx 11.31`] } });

  G('Circles/Segment area', 'Area of a circular segment|Aire d’un segment circulaire|Área de un segmento circular|弓形の面積|弓形面积',
    { s: R`A segment is the part of a sector beyond its chord: sector minus the isosceles triangle. The triangle has two sides $r$ and angle $\theta$, area $\tfrac12 r^2\sin\theta$. Hence $\tfrac12 r^2(\theta - \sin\theta)$ — with $\theta$ in radians.|Un segment est la partie d’un secteur au-delà de sa corde : secteur moins le triangle isocèle. Le triangle a deux côtés $r$ et un angle $\theta$, d’aire $\tfrac12 r^2\sin\theta$. D’où $\tfrac12 r^2(\theta - \sin\theta)$ — avec $\theta$ en radians.|Un segmento es la parte de un sector más allá de su cuerda: sector menos el triángulo isósceles. El triángulo tiene dos lados $r$ y ángulo $\theta$, área $\tfrac12 r^2\sin\theta$. De ahí $\tfrac12 r^2(\theta - \sin\theta)$, con $\theta$ en radianes.|弓形は扇形から二等辺三角形（面積 $\tfrac12 r^2\sin\theta$）を引いたもの：$\tfrac12 r^2(\theta - \sin\theta)$（$\theta$ はラジアン）。|弓形是扇形减去等腰三角形（面积 $\tfrac12 r^2\sin\theta$）：$\tfrac12 r^2(\theta - \sin\theta)$（$\theta$ 用弧度）。`,
      a: [Y(R`S = \tfrac12 r^2(\theta - \sin\theta)`, { s: 30 }), S2([0, 0.6], 2.3), CI(Q(0, 0), 2, { c: 'b', fill: 0.05 }), ...SEQ([POLY([Q(0, 0), ON(2, 30), ON(2, 150)], { c: 'b', fill: 0.2 }), SEGMT(2, Math.PI / 6, 5 * Math.PI / 6, 'y', 0.4)])] },
    { s: R`$r = 6$, $\theta = \tfrac\pi3$: $\tfrac12\cdot 36\left(\tfrac\pi3 - \tfrac{\sqrt3}{2}\right) = 6\pi - 9\sqrt3 \approx 3.26$.|$r = 6$, $\theta = \tfrac\pi3$ : $6\pi - 9\sqrt3 \approx 3{,}26$.|$r = 6$, $\theta = \tfrac\pi3$: $6\pi - 9\sqrt3 \approx 3{,}26$.|約 3.26。|约 3.26。`,
      a: [Y(R`18\left(\frac\pi3 - \frac{\sqrt3}{2}\right) = 6\pi - 9\sqrt3`)] },
    { a: [F(R`r = 2,\quad \theta = \frac\pi2`)],
      ex: { k: 'val', v: 'pi-2', q: R`Find the area of the segment of a circle of radius 2 cut off by a chord subtending $90°$.|Calculez l’aire du segment d’un cercle de rayon 2 délimité par une corde interceptant $90°$.|Halla el área del segmento de una circunferencia de radio 2 cortado por una cuerda de $90°$.|半径 2 の円で中心角 $90°$ の弦が切り取る弓形の面積を求めよ。|半径 2 的圆中圆心角 $90°$ 的弦所截弓形面积是多少？`, sol: [R`\tfrac12\cdot 4\left(\frac\pi2 - 1\right)`, R`= \pi - 2 \approx 1.14`] } });

  // =============================== Circle theorems ===============================
  const INS = (deg = 100) => [S2([0, 0.2], 2.4), CI(Q(0, 0), 2, { c: 'b', fill: 0.04 }), ...SEQ([SG(Q(0, 0), ON(2, -90 - deg / 2), { c: 'p' }), SG(Q(0, 0), ON(2, -90 + deg / 2), { c: 'p' }), SG(ON(2, 110), ON(2, -90 - deg / 2), { c: 'y' }), SG(ON(2, 110), ON(2, -90 + deg / 2), { c: 'y' }), LB(ON(2.3, -90 - deg / 2), 'A', { c: 'chalk' }), LB(ON(2.3, -90 + deg / 2), 'B', { c: 'chalk' }), LB(ON(2.3, 110), 'P', { c: 'chalk' }), PT(Q(0, 0), 'O', { c: 'o' })])];
  G('Circle theorems/Inscribed angle', 'The inscribed angle theorem|Le théorème de l’angle inscrit|El teorema del ángulo inscrito|円周角の定理|圆周角定理',
    { s: R`An angle with its vertex on the circle is half the central angle on the same arc. So all inscribed angles on the same arc are equal, wherever $P$ sits on the major arc.|Un angle dont le sommet est sur le cercle vaut la moitié de l’angle au centre interceptant le même arc. Tous les angles inscrits interceptant le même arc sont donc égaux, où que soit $P$ sur le grand arc.|Un ángulo con vértice en la circunferencia es la mitad del ángulo central que abarca el mismo arco. Así todos los ángulos inscritos en el mismo arco son iguales, esté donde esté $P$ en el arco mayor.|円周上に頂点をもつ角は同じ弧に対する中心角の半分。同じ弧に対する円周角は $P$ の位置によらず等しい。|顶点在圆上的角等于同弧所对圆心角的一半。所以同弧上的圆周角都相等，不论 $P$ 在优弧何处。`,
      a: [Y(R`\angle APB = \tfrac12\,\angle AOB`, { s: 30 }), ...INS(100)] },
    { s: R`A central angle of $100°$: every inscribed angle on that arc is $50°$.|Angle au centre $100°$ : tout angle inscrit sur cet arc vaut $50°$.|Ángulo central de $100°$: todo ángulo inscrito en ese arco mide $50°$.|$50°$。|$50°$。`,
      a: [Y(R`\angle APB = \tfrac12\cdot 100^\circ = 50^\circ`)] },
    { a: [F(R`\angle APB = 35^\circ`), ...INS(70)],
      ex: { k: 'val', v: '70', q: R`An inscribed angle is $35°$. Find the central angle on the same arc.|Un angle inscrit vaut $35°$. Trouvez l’angle au centre interceptant le même arc.|Un ángulo inscrito mide $35°$. Halla el ángulo central del mismo arco.|円周角が $35°$。同じ弧に対する中心角は？|圆周角为 $35°$，同弧所对的圆心角是多少？`, sol: [R`\angle AOB = 2\cdot 35^\circ`, R`= 70^\circ`] } });

  G('Circle theorems/Angle in a semicircle', 'The angle in a semicircle|L’angle inscrit dans un demi-cercle|El ángulo inscrito en una semicircunferencia|半円に対する円周角|半圆上的圆周角',
    { s: R`When $AB$ is a diameter, the central angle is $180°$, so the inscribed angle is $90°$ (Thales). Any triangle drawn on a diameter with its third vertex on the circle is right-angled — Pythagoras applies.|Quand $AB$ est un diamètre, l’angle au centre vaut $180°$, donc l’angle inscrit $90°$ (Thalès). Tout triangle construit sur un diamètre avec son troisième sommet sur le cercle est rectangle — Pythagore s’applique.|Si $AB$ es un diámetro, el ángulo central es $180°$, así que el inscrito es $90°$ (Tales). Todo triángulo sobre un diámetro con el tercer vértice en la circunferencia es rectángulo: se aplica Pitágoras.|$AB$ が直径なら中心角 $180°$ で円周角は $90°$（タレス）。直径を一辺とし残りの頂点が円周上の三角形は直角三角形。|$AB$ 为直径时圆心角 $180°$，圆周角为 $90°$（泰勒斯）。以直径为边、第三个顶点在圆上的三角形是直角三角形——可用勾股定理。`,
      a: [Y(R`AB = 2r \Rightarrow \angle APB = 90^\circ`, { s: 28 }), S2([0, 0.3], 2.4), CI(Q(0, 0), 2, { c: 'b', fill: 0.04 }), ...SEQ([SG(Q(-2, 0), Q(2, 0), { c: 'p' }), SG(Q(-2, 0), ON(2, 65), { c: 'y' }), SG(Q(2, 0), ON(2, 65), { c: 'y' }), LB(Q(-2.3, 0), 'A', { c: 'chalk' }), LB(Q(2.3, 0), 'B', { c: 'chalk' }), LB(ON(2.3, 65), 'P', { c: 'chalk' })])] },
    { s: R`Diameter 13 and chord $PA = 5$: the triangle is right-angled at $P$, so $PB = \sqrt{169 - 25} = 12$.|Diamètre 13, $PA = 5$ : rectangle en $P$, donc $PB = 12$.|Diámetro 13, $PA = 5$: rectángulo en $P$, así que $PB = 12$.|$PB = 12$。|$PB = 12$。`,
      a: [Y(R`PB = \sqrt{13^2 - 5^2} = 12`)] },
    { a: [F(R`AB = 10\ (\text{diameter}),\quad PA = 6`)],
      ex: { k: 'val', v: '8', q: R`$AB = 10$ is a diameter and $P$ is on the circle with $PA = 6$. Find $PB$.|$AB = 10$ est un diamètre et $P$ est sur le cercle avec $PA = 6$. Calculez $PB$.|$AB = 10$ es un diámetro y $P$ está en la circunferencia con $PA = 6$. Halla $PB$.|$AB = 10$ は直径、$P$ は円周上で $PA = 6$。$PB$ を求めよ。|$AB = 10$ 为直径，$P$ 在圆上且 $PA = 6$，求 $PB$。`, sol: [R`\angle APB = 90^\circ`, R`PB = \sqrt{100 - 36} = 8`] } });

  G('Circle theorems/Cyclic quadrilateral', 'Cyclic quadrilaterals|Quadrilatères inscriptibles|Cuadriláteros inscritos|円に内接する四角形|圆内接四边形',
    { s: R`If the four vertices lie on a circle, opposite angles stand on arcs that make up the whole circle; their central angles add to $360°$, so the angles add to $180°$. Conversely, opposite angles adding to $180°$ means the quadrilateral is cyclic.|Si les quatre sommets sont sur un cercle, deux angles opposés interceptent des arcs qui forment le cercle entier ; leurs angles au centre font $360°$, donc les angles font $180°$. Réciproquement, des angles opposés supplémentaires rendent le quadrilatère inscriptible.|Si los cuatro vértices están en una circunferencia, los ángulos opuestos abarcan arcos que forman la circunferencia entera; sus ángulos centrales suman $360°$, así que los ángulos suman $180°$. Al revés, si los opuestos suman $180°$, el cuadrilátero es inscriptible.|4 頂点が円周上なら、対角は合わせて円全体の弧に対する角で、中心角の和 $360°$ より対角の和は $180°$。逆も成り立つ。|四个顶点在圆上时，对角所对的弧合起来是整个圆，圆心角之和 $360°$，所以对角之和 $180°$。反之对角互补的四边形可内接于圆。`,
      a: [Y(R`A + C = B + D = 180^\circ`, { s: 30 }), S2([0, 0], 2.4), CI(Q(0, 0), 2, { c: 'b', fill: 0.04 }), POLY([ON(2, 200), ON(2, 300), ON(2, 30), ON(2, 110)], { c: 'y', fill: 0.18 }), LB(ON(2.35, 200), 'A', { c: 'chalk' }), LB(ON(2.35, 300), 'B', { c: 'chalk' }), LB(ON(2.35, 30), 'C', { c: 'chalk' }), LB(ON(2.35, 110), 'D', { c: 'chalk' })] },
    { s: R`$A = 80°$: the opposite angle $C = 100°$.|$A = 80°$ : $C = 100°$.|$A = 80°$: $C = 100°$.|$C = 100°$。|$C = 100°$。`,
      a: [Y(R`C = 180^\circ - 80^\circ = 100^\circ`)] },
    { a: [F(R`B = 2D`)],
      ex: { k: 'val', v: '60', q: R`In a cyclic quadrilateral $ABCD$, $B = 2D$. Find $D$ in degrees.|Dans un quadrilatère inscrit $ABCD$, $B = 2D$. Trouvez $D$ en degrés.|En un cuadrilátero inscrito $ABCD$, $B = 2D$. Halla $D$ en grados.|円に内接する四角形 $ABCD$ で $B = 2D$。$D$（度）を求めよ。|圆内接四边形 $ABCD$ 中 $B = 2D$，求 $D$（度）。`, sol: [R`2D + D = 180^\circ`, R`D = 60^\circ`] } });

  const TAN = [S2([1.2, 0], 3), CI(Q(0, 0), 1.5, { c: 'b', fill: 0.04 }), ...SEQ([SG(Q(0, 0), Q(1.5 * 0.6, 1.5 * 0.8), { c: 'chalk' }), SG(Q(3.75, 0), Q(0.9, 1.2), { c: 'y' }), SG(Q(3.75, 0), Q(0.9, -1.2), { c: 'y' }), SG(Q(0, 0), Q(3.75, 0), { c: 'p', dash: true }), SG(Q(0, 0), Q(0.9, -1.2), { c: 'chalk' }), PT(Q(0, 0), 'O', { c: 'o' }), PT(Q(3.75, 0), 'P', { c: 'o' }), LB(Q(0.75, 1.45), 'T₁', { c: 'chalk' }), LB(Q(0.75, -1.5), 'T₂', { c: 'chalk' })])];
  G('Circle theorems/Tangent and radius', 'Tangent and radius|Tangente et rayon|Tangente y radio|接線と半径|切线与半径',
    { s: R`The tangent touches the circle at one point $T$, and there it is perpendicular to the radius $OT$. So $O$, $T$ and an outside point $P$ form a right triangle with hypotenuse $OP$: $PT^2 = OP^2 - r^2$.|La tangente touche le cercle en un point $T$, où elle est perpendiculaire au rayon $OT$. $O$, $T$ et un point extérieur $P$ forment donc un triangle rectangle d’hypoténuse $OP$ : $PT^2 = OP^2 - r^2$.|La tangente toca la circunferencia en un punto $T$ y ahí es perpendicular al radio $OT$. Así $O$, $T$ y un punto exterior $P$ forman un triángulo rectángulo de hipotenusa $OP$: $PT^2 = OP^2 - r^2$.|接線は接点 $T$ で半径 $OT$ に垂直。$O$, $T$ と外の点 $P$ は斜辺 $OP$ の直角三角形：$PT^2 = OP^2 - r^2$。|切线在切点 $T$ 处垂直于半径 $OT$。所以 $O$、$T$ 与外点 $P$ 构成斜边为 $OP$ 的直角三角形：$PT^2 = OP^2 - r^2$。`,
      a: [Y(R`OT \perp t`, { s: 30 }), ...TAN] },
    { s: R`$r = 5$ and $OP = 13$: the tangent from $P$ has length $\sqrt{169 - 25} = 12$.|$r = 5$, $OP = 13$ : $PT = 12$.|$r = 5$, $OP = 13$: $PT = 12$.|$PT = 12$。|$PT = 12$。`,
      a: [Y(R`PT = \sqrt{13^2 - 5^2} = 12`)] },
    { a: [F(R`r = 8,\quad PT = 15`), ...TAN],
      ex: { k: 'val', v: '17', q: R`A circle has radius 8 and the tangent from $P$ has length 15. Find the distance from $P$ to the centre.|Un cercle a un rayon de 8 et la tangente issue de $P$ mesure 15. Calculez la distance de $P$ au centre.|Una circunferencia tiene radio 8 y la tangente desde $P$ mide 15. Halla la distancia de $P$ al centro.|半径 8、$P$ からの接線の長さ 15。$P$ と中心の距離を求めよ。|半径 8，从 $P$ 引的切线长 15，求 $P$ 到圆心的距离。`, sol: [R`OP^2 = 8^2 + 15^2 = 289`, R`OP = 17`] } });

  G('Circle theorems/Equal tangents', 'Equal tangents|Tangentes égales|Tangentes iguales|接線の長さは等しい|切线长相等',
    { s: R`The two tangents from an outside point are equally long: the right triangles $OPT_1$ and $OPT_2$ share the hypotenuse $OP$ and have equal legs $r$. Consequence for a quadrilateral around a circle: opposite sides have equal sums (Pitot).|Les deux tangentes issues d’un point extérieur ont la même longueur : les triangles rectangles $OPT_1$ et $OPT_2$ ont même hypoténuse $OP$ et des côtés égaux $r$. Pour un quadrilatère circonscrit : les sommes des côtés opposés sont égales (Pitot).|Las dos tangentes desde un punto exterior miden lo mismo: los triángulos rectángulos $OPT_1$ y $OPT_2$ comparten la hipotenusa $OP$ y tienen catetos iguales $r$. Para un cuadrilátero circunscrito: los lados opuestos suman igual (Pitot).|外の点からの 2 本の接線は等しい（直角三角形 $OPT_1$, $OPT_2$ は斜辺 $OP$ と脚 $r$ を共有）。円に外接する四角形では対辺の和が等しい（ピトー）。|从外点引的两条切线等长：直角三角形 $OPT_1$、$OPT_2$ 斜边 $OP$ 相同，直角边都为 $r$。推论：圆外切四边形对边之和相等（皮托定理）。`,
      a: [Y(R`PT_1 = PT_2`, { s: 30 }), ...TAN] },
    { s: R`A quadrilateral around a circle: each vertex sends two equal tangent pieces, so $AB + CD = BC + DA$. With $AB = 7$, $BC = 6$, $CD = 9$: $DA = 10$.|Quadrilatère circonscrit : $AB + CD = BC + DA$. Avec $AB = 7$, $BC = 6$, $CD = 9$ : $DA = 10$.|Cuadrilátero circunscrito: $AB + CD = BC + DA$. Con $AB = 7$, $BC = 6$, $CD = 9$: $DA = 10$.|$DA = 10$。|$DA = 10$。`,
      a: [Y(R`AB + CD = BC + DA`), F(R`7 + 9 = 6 + DA \Rightarrow DA = 10`)] },
    { a: [F(R`AB = 8,\quad BC = 11,\quad CD = 12`)],
      ex: { k: 'val', v: '9', q: R`A quadrilateral $ABCD$ is drawn around a circle, with $AB = 8$, $BC = 11$, $CD = 12$. Find $DA$.|Un quadrilatère $ABCD$ est circonscrit à un cercle, avec $AB = 8$, $BC = 11$, $CD = 12$. Calculez $DA$.|Un cuadrilátero $ABCD$ está circunscrito a una circunferencia, con $AB = 8$, $BC = 11$, $CD = 12$. Halla $DA$.|円に外接する四角形 $ABCD$ で $AB = 8$, $BC = 11$, $CD = 12$。$DA$ を求めよ。|圆外切四边形 $ABCD$ 中 $AB = 8$，$BC = 11$，$CD = 12$，求 $DA$。`, sol: [R`8 + 12 = 11 + DA`, R`DA = 9`] } });

  G('Circle theorems/Power of a point', 'Power of a point|Puissance d’un point|Potencia de un punto|方べきの定理|圆幂定理',
    { s: R`Through a point $P$ draw any line meeting the circle at $A$ and $B$: the product $PA\cdot PB$ is the same for every line (similar triangles). For a tangent the two points merge into $T$, giving $PT^2$. It works for chords crossing inside the circle too.|Par un point $P$, toute droite coupant le cercle en $A$ et $B$ donne le même produit $PA\cdot PB$ (triangles semblables). Pour une tangente les deux points se confondent en $T$ : $PT^2$. Cela vaut aussi pour deux cordes qui se coupent à l’intérieur.|Por un punto $P$, toda recta que corte la circunferencia en $A$ y $B$ da el mismo producto $PA\cdot PB$ (triángulos semejantes). Para una tangente los dos puntos se juntan en $T$: $PT^2$. También vale para cuerdas que se cortan dentro.|点 $P$ を通り円と $A$, $B$ で交わる直線では $PA\cdot PB$ が一定（相似）。接線なら 2 点が $T$ に重なり $PT^2$。円の内部で交わる弦でも成り立つ。|过点 $P$ 的任意直线交圆于 $A$、$B$，积 $PA\cdot PB$ 都相同（相似三角形）。切线时两点重合为 $T$，得 $PT^2$。弦在圆内相交时也成立。`,
      a: [Y(R`PA\cdot PB = PC\cdot PD = PT^2`, { s: 28 }), S2([1.2, 0], 2.8), CI(Q(0, 0), 1.6, { c: 'b', fill: 0.04 }), ...SEQ([SG(Q(4, 0), Q(-1.6, 0), { c: 'y' }), SG(Q(4, 0), Q(-0.9, 1.32), { c: 'p' }), SG(Q(4, 0), Q(0.64, 1.466), { c: 'g' }), PT(Q(4, 0), 'P', { c: 'o' }), LB(Q(1.6, -0.3), 'A', { c: 'chalk' }), LB(Q(-1.85, -0.25), 'B', { c: 'chalk' }), LB(Q(0.6, 1.75), 'T', { c: 'g' })])] },
    { s: R`$PA = 4$ and $PB = 9$ on a secant: the tangent from $P$ has $PT^2 = 36$, so $PT = 6$.|$PA = 4$, $PB = 9$ : $PT^2 = 36$, $PT = 6$.|$PA = 4$, $PB = 9$: $PT^2 = 36$, $PT = 6$.|$PT = 6$。|$PT = 6$。`,
      a: [Y(R`PT = \sqrt{4\cdot 9} = 6`)] },
    { a: [F(R`PA = 3,\ PB = 8,\ PC = 4\ \text{(chords through } P)`, { s: 22 })],
      ex: { k: 'val', v: '6', q: R`Two chords $AB$ and $CD$ cross at $P$ inside a circle, with $PA = 3$, $PB = 8$, $PC = 4$. Find $PD$.|Deux cordes $AB$ et $CD$ se coupent en $P$ à l’intérieur d’un cercle, avec $PA = 3$, $PB = 8$, $PC = 4$. Calculez $PD$.|Dos cuerdas $AB$ y $CD$ se cortan en $P$ dentro de una circunferencia, con $PA = 3$, $PB = 8$, $PC = 4$. Halla $PD$.|円の内部で弦 $AB$, $CD$ が $P$ で交わり $PA = 3$, $PB = 8$, $PC = 4$。$PD$ は？|圆内两弦 $AB$、$CD$ 交于 $P$，$PA = 3$，$PB = 8$，$PC = 4$，求 $PD$。`, sol: [R`3\cdot 8 = 4\cdot PD`, R`PD = 6`] } });

  // =============================== Polygons and quadrilaterals ===============================
  G('Polygons and quadrilaterals/Interior angle sum', 'Sum of the interior angles|Somme des angles intérieurs|Suma de los ángulos interiores|内角の和|内角和',
    { s: R`From one vertex, the diagonals cut an $n$-gon into $n - 2$ triangles, each contributing $180°$. So the angles add to $(n - 2)\cdot 180°$: 360° for a quadrilateral, 540° for a pentagon…|Depuis un sommet, les diagonales découpent un polygone à $n$ côtés en $n - 2$ triangles, chacun apportant $180°$. La somme vaut $(n - 2)\cdot 180°$ : 360° pour un quadrilatère, 540° pour un pentagone…|Desde un vértice, las diagonales dividen un polígono de $n$ lados en $n - 2$ triángulos de $180°$ cada uno. Así los ángulos suman $(n - 2)\cdot 180°$: 360° el cuadrilátero, 540° el pentágono…|1 つの頂点からの対角線で $n$ 角形は $n - 2$ 個の三角形に分かれ、それぞれ $180°$。和は $(n - 2)\cdot 180°$。|从一个顶点出发的对角线把 $n$ 边形分成 $n - 2$ 个三角形，每个 $180°$。所以内角和为 $(n - 2)\cdot 180°$。`,
      a: [Y(R`(n - 2)\cdot 180^\circ`, { s: 30 }), S2([0, 0], 2.2), REG(6, 1.9), ...SEQ([2, 3, 4].map(k => SG(ON(1.9, 90), ON(1.9, 90 + 60 * k), { c: 'y' })), 300, 250)] },
    { s: R`A hexagon splits into 4 triangles: $4\cdot 180° = 720°$.|Un hexagone se découpe en 4 triangles : $720°$.|Un hexágono se divide en 4 triángulos: $720°$.|$720°$。|$720°$。`,
      a: [Y(R`(6 - 2)\cdot 180^\circ = 720^\circ`)] },
    { a: [F(R`n = 10`)],
      ex: { k: 'val', v: '1440', q: R`Find the sum of the interior angles of a decagon, in degrees.|Calculez la somme des angles intérieurs d’un décagone (en degrés).|Halla la suma de los ángulos interiores de un decágono, en grados.|十角形の内角の和（度）を求めよ。|十边形的内角和是多少度？`, sol: [R`(10 - 2)\cdot 180^\circ`, R`= 1440^\circ`] } });

  G('Polygons and quadrilaterals/Regular polygon angle', 'Angle of a regular polygon|Angle d’un polygone régulier|Ángulo de un polígono regular|正多角形の内角|正多边形的内角',
    { s: R`In a regular polygon all angles are equal, so divide the sum by $n$. Easier: each exterior angle is $\tfrac{360°}{n}$ (walking round, you turn a full turn), and the interior angle is $180°$ minus that.|Dans un polygone régulier tous les angles sont égaux : on divise la somme par $n$. Plus simple : chaque angle extérieur vaut $\tfrac{360°}{n}$ (en faisant le tour on tourne d’un tour complet), et l’angle intérieur vaut $180°$ moins cela.|En un polígono regular todos los ángulos son iguales, así que divide la suma entre $n$. Más fácil: cada ángulo exterior es $\tfrac{360°}{n}$ (al recorrerlo se da una vuelta completa) y el interior es $180°$ menos eso.|正多角形では内角は等しいので和を $n$ で割る。外角は $\tfrac{360°}{n}$（一周で 1 回転）なので内角は $180°$ からそれを引く方が簡単。|正多边形各角相等，内角和除以 $n$。更简单：每个外角为 $\tfrac{360°}{n}$（绕一圈转一整周），内角是 $180°$ 减去它。`,
      a: [Y(R`\frac{(n - 2)\cdot 180^\circ}{n} = 180^\circ - \frac{360^\circ}{n}`, { s: 26 }), S2([0, 0], 2.2), REG(8, 1.9, 'b', 0.16, Math.PI / 8)] },
    { s: R`Regular octagon: exterior $45°$, interior $135°$.|Octogone régulier : extérieur $45°$, intérieur $135°$.|Octógono regular: exterior $45°$, interior $135°$.|$135°$。|$135°$。`,
      a: [Y(R`180^\circ - \frac{360^\circ}{8} = 135^\circ`)] },
    { a: [F(R`\text{interior angle } 150^\circ`)],
      ex: { k: 'val', v: '12', q: R`Each interior angle of a regular polygon is $150°$. How many sides does it have?|Chaque angle intérieur d’un polygone régulier vaut $150°$. Combien a-t-il de côtés ?|Cada ángulo interior de un polígono regular mide $150°$. ¿Cuántos lados tiene?|正多角形の内角が $150°$。何角形か。|正多边形每个内角 $150°$，它有几条边？`, sol: [R`\text{exterior } 30^\circ`, R`n = \frac{360}{30} = 12`] } });

  G('Polygons and quadrilaterals/Diagonals', 'Number of diagonals|Nombre de diagonales|Número de diagonales|対角線の本数|对角线条数',
    { s: R`Each vertex joins the $n - 3$ vertices that are not itself or its neighbours. That gives $n(n - 3)$, but every diagonal was counted from both ends, so divide by 2.|Chaque sommet est relié aux $n - 3$ sommets qui ne sont ni lui ni ses voisins. Cela donne $n(n - 3)$, mais chaque diagonale est comptée deux fois : on divise par 2.|Cada vértice se une a los $n - 3$ vértices que no son él ni sus vecinos. Eso da $n(n - 3)$, pero cada diagonal se cuenta dos veces: divide entre 2.|各頂点は自分と隣以外の $n - 3$ 個と結ばれる。$n(n - 3)$ は両端から 2 回数えているので 2 で割る。|每个顶点与除自身和相邻顶点外的 $n - 3$ 个顶点相连，得 $n(n - 3)$，但每条对角线从两端各数一次，除以 2。`,
      a: [Y(R`\frac{n(n - 3)}{2}`, { s: 30 }), S2([0, 0], 2.2), REG(8, 1.9, 'b', 0.08, Math.PI / 8), ...SEQ((() => { const o = []; for (let i = 0; i < 8; i++) for (let j = i + 2; j < 8; j++) if (!(i === 0 && j === 7)) o.push(SG(ON(1.9, 22.5 + 45 * i), ON(1.9, 22.5 + 45 * j), { c: 'y', w: 1.2 })); return o; })(), 200, 40)] },
    { s: R`Octagon: $\tfrac{8\cdot 5}{2} = 20$ diagonals, all drawn in the picture.|Octogone : $\tfrac{8\cdot 5}{2} = 20$ diagonales.|Octógono: $\tfrac{8\cdot 5}{2} = 20$ diagonales.|20 本。|20 条。`,
      a: [Y(R`\frac{8\cdot 5}{2} = 20`)] },
    { a: [F(R`n = 15`)],
      ex: { k: 'val', v: '90', q: R`How many diagonals does a 15-sided polygon have?|Combien de diagonales a un polygone à 15 côtés ?|¿Cuántas diagonales tiene un polígono de 15 lados?|十五角形の対角線は何本か。|十五边形有多少条对角线？`, sol: [R`\frac{15\cdot 12}{2}`, R`= 90`] } });

  G('Polygons and quadrilaterals/Regular polygon area', 'Area of a regular polygon|Aire d’un polygone régulier|Área de un polígono regular|正多角形の面積|正多边形面积',
    { s: R`Join the centre to the vertices: $n$ equal isosceles triangles, each with two sides $R$ and angle $\tfrac{2\pi}{n}$. Or use the apothem $a$ (centre to side): each triangle is $\tfrac12\cdot\text{side}\cdot a$, so $S = \tfrac12 P a$.|On joint le centre aux sommets : $n$ triangles isocèles égaux, chacun de côtés $R$ et d’angle $\tfrac{2\pi}{n}$. Ou avec l’apothème $a$ (centre–côté) : chaque triangle vaut $\tfrac12\cdot\text{côté}\cdot a$, donc $S = \tfrac12 P a$.|Une el centro con los vértices: $n$ triángulos isósceles iguales, con dos lados $R$ y ángulo $\tfrac{2\pi}{n}$. O usa la apotema $a$ (centro–lado): cada triángulo es $\tfrac12\cdot\text{lado}\cdot a$, así que $S = \tfrac12 P a$.|中心と頂点を結ぶと $n$ 個の合同な二等辺三角形（2 辺 $R$、角 $\tfrac{2\pi}{n}$）。辺心距 $a$ を使えば各三角形は $\tfrac12\cdot$ 辺 $\cdot a$ で $S = \tfrac12 P a$。|连接中心与各顶点：得 $n$ 个全等的等腰三角形，两边为 $R$、顶角 $\tfrac{2\pi}{n}$。或用边心距 $a$：每个三角形为 $\tfrac12\cdot$ 边 $\cdot a$，故 $S = \tfrac12 P a$。`,
      a: [Y(R`S = \tfrac12 P a = \tfrac12 nR^2\sin\frac{2\pi}{n}`, { s: 26 }), S2([0, 0], 2.2), REG(6, 1.9, 'b', 0.12, 0), ...SEQ([0, 1, 2, 3, 4, 5].map(k => SG(Q(0, 0), ON(1.9, 60 * k), { c: 'y' })), 200, 120)] },
    { s: R`Regular hexagon with side 2 (so $R = 2$): $S = \tfrac12\cdot 6\cdot 4\cdot\sin 60° = 6\sqrt3 \approx 10.39$ — six equilateral triangles of area $\sqrt3$.|Hexagone régulier de côté 2 : $S = 6\sqrt3$ — six triangles équilatéraux d’aire $\sqrt3$.|Hexágono regular de lado 2: $S = 6\sqrt3$, seis triángulos equiláteros de área $\sqrt3$.|$6\sqrt3$。|$6\sqrt3$。`,
      a: [Y(R`\tfrac12\cdot 6\cdot 2^2\cdot\frac{\sqrt3}{2} = 6\sqrt3`)] },
    { a: [F(R`n = 4,\quad R = 1`)],
      ex: { k: 'val', v: '2', q: R`Find the area of a square inscribed in a circle of radius 1.|Calculez l’aire d’un carré inscrit dans un cercle de rayon 1.|Halla el área de un cuadrado inscrito en una circunferencia de radio 1.|半径 1 の円に内接する正方形の面積を求めよ。|内接于半径 1 的圆的正方形面积是多少？`, sol: [R`\tfrac12\cdot 4\cdot 1^2\cdot\sin 90^\circ`, R`= 2`] } });

  G('Polygons and quadrilaterals/Parallelogram, rhombus, trapezoid', 'Parallelogram, rhombus and trapezoid|Parallélogramme, losange et trapèze|Paralelogramo, rombo y trapecio|平行四辺形・ひし形・台形|平行四边形、菱形与梯形',
    { s: R`Slide a triangle from one end of a parallelogram to the other and you get a rectangle: $bh$. A rhombus is half of the rectangle built on its diagonals. Two copies of a trapezoid, one turned round, make a parallelogram of base $a + b$.|En déplaçant un triangle d’un bout à l’autre d’un parallélogramme on obtient un rectangle : $bh$. Un losange est la moitié du rectangle construit sur ses diagonales. Deux trapèzes, l’un retourné, forment un parallélogramme de base $a + b$.|Mueve un triángulo de un extremo al otro de un paralelogramo y sale un rectángulo: $bh$. Un rombo es la mitad del rectángulo construido sobre sus diagonales. Dos trapecios, uno girado, forman un paralelogramo de base $a + b$.|平行四辺形は三角形を移して長方形に：$bh$。ひし形は対角線でできる長方形の半分。台形 2 つ（1 つを回す）で底辺 $a + b$ の平行四辺形。|平行四边形把一端的三角形移到另一端就成矩形：$bh$。菱形是以对角线为边的矩形的一半。两个梯形（一个转过来）拼成底为 $a + b$ 的平行四边形。`,
      a: [Y(R`bh,\qquad \frac{d_1 d_2}{2},\qquad \frac{(a + b)h}{2}`, { s: 28 }), S2([3.5, 1], 4), ...SEQ([POLY([Q(0, 0), Q(3, 0), Q(4, 2), Q(1, 2)], { c: 'b', fill: 0.2 }), POLY([Q(5, 1), Q(6, 0), Q(7, 1), Q(6, 2)], { c: 'p', fill: 0.2 }), SG(Q(5, 1), Q(7, 1), { c: 'p', dash: true }), SG(Q(6, 0), Q(6, 2), { c: 'p', dash: true })])] },
    { s: R`Trapezoid with bases 5 and 9 and height 4: $\tfrac{14\cdot 4}{2} = 28$. Rhombus with diagonals 6 and 8: $24$.|Trapèze de bases 5 et 9, hauteur 4 : $28$. Losange de diagonales 6 et 8 : $24$.|Trapecio de bases 5 y 9, altura 4: $28$. Rombo de diagonales 6 y 8: $24$.|28 と 24。|28 与 24。`,
      a: [F(R`\frac{(5 + 9)\cdot 4}{2} = 28`), Y(R`\frac{6\cdot 8}{2} = 24`)] },
    { a: [F(R`a = 7,\quad b = 13,\quad h = 5`)],
      ex: { k: 'val', v: '50', q: R`Find the area of a trapezoid with bases 7 and 13 and height 5.|Calculez l’aire d’un trapèze de bases 7 et 13 et de hauteur 5.|Halla el área de un trapecio de bases 7 y 13 y altura 5.|上底 7、下底 13、高さ 5 の台形の面積を求めよ。|上底 7、下底 13、高 5 的梯形面积是多少？`, sol: [R`\frac{(7 + 13)\cdot 5}{2}`, R`= 50`] } });

  G('Polygons and quadrilaterals/Shoelace formula', 'The shoelace formula|La formule du lacet|La fórmula del cordón|靴ひも公式|鞋带公式',
    { s: R`List the vertices in order around the polygon (repeat the first at the end). Multiply crosswise, $x_i y_{i+1} - x_{i+1} y_i$, add, halve, take the absolute value. It works for any simple polygon given by coordinates.|On liste les sommets dans l’ordre (en répétant le premier à la fin). On multiplie en croix, $x_i y_{i+1} - x_{i+1} y_i$, on additionne, on divise par deux et on prend la valeur absolue. Cela marche pour tout polygone simple donné par ses coordonnées.|Escribe los vértices en orden (repite el primero al final). Multiplica en cruz, $x_i y_{i+1} - x_{i+1} y_i$, suma, divide entre dos y toma el valor absoluto. Sirve para cualquier polígono simple dado por coordenadas.|頂点を順に並べ（最初の点を最後にもう一度）、たすき掛け $x_i y_{i+1} - x_{i+1} y_i$ を足して半分にし絶対値。座標で与えられた単純多角形ならどれでも使える。|按顺序列出顶点（末尾重复第一个），交叉相乘 $x_i y_{i+1} - x_{i+1} y_i$，求和、除以 2、取绝对值。适用于坐标给出的任意简单多边形。`,
      a: [Y(R`S = \tfrac12\left\lvert\sum_i (x_i y_{i+1} - x_{i+1} y_i)\right\rvert`, { s: 26 }), S2([2, 2.5], 3.2), POLY([Q(0, 0), Q(4, 0), Q(4, 3), Q(0, 5)], { c: 'y', fill: 0.2 }), ...SEQ([[0, 0], [4, 0], [4, 3], [0, 5]].map(([x, y]) => PT(Q(x, y), `(${x}, ${y})`, { c: 'o' })), 300, 120)] },
    { s: R`$(0, 0), (4, 0), (4, 3), (0, 5)$: $0 + 12 + 20 + 0 = 32$, so $S = 16$ — a right trapezoid with bases 3 and 5 and height 4.|$(0, 0), (4, 0), (4, 3), (0, 5)$ : somme $32$, donc $S = 16$ — un trapèze rectangle de bases 3 et 5, hauteur 4.|$(0, 0), (4, 0), (4, 3), (0, 5)$: suma $32$, así que $S = 16$, un trapecio rectángulo de bases 3 y 5 y altura 4.|$S = 16$。|$S = 16$。`,
      a: [F(R`(0 - 0) + (12 - 0) + (20 - 0) + (0 - 0) = 32`, { s: 22 }), Y(R`S = 16`)] },
    { a: [F(R`(1, 0),\ (5, 1),\ (4, 4),\ (0, 3)`)],
      ex: { k: 'val', v: '13', q: R`Find the area of the quadrilateral with vertices $(1, 0)$, $(5, 1)$, $(4, 4)$, $(0, 3)$, in that order.|Calculez l’aire du quadrilatère de sommets $(1, 0)$, $(5, 1)$, $(4, 4)$, $(0, 3)$ dans cet ordre.|Halla el área del cuadrilátero de vértices $(1, 0)$, $(5, 1)$, $(4, 4)$, $(0, 3)$ en ese orden.|頂点 $(1, 0)$, $(5, 1)$, $(4, 4)$, $(0, 3)$ の四角形の面積を求めよ。|求顶点依次为 $(1, 0)$、$(5, 1)$、$(4, 4)$、$(0, 3)$ 的四边形面积。`, sol: [R`1 + 16 + 12 - 3 = 26`, R`S = 13`] } });

  // =============================== Solids ===============================
  const BOX = (a, b, c, diag = true) => { const V = [[0, 0, 0], [a, 0, 0], [a, b, 0], [0, b, 0], [0, 0, c], [a, 0, c], [a, b, c], [0, b, c]], E = [[0, 1], [1, 2], [2, 3], [3, 0], [4, 5], [5, 6], [6, 7], [7, 4], [0, 4], [1, 5], [2, 6], [3, 7]];
    return [['3d', { c: [a / 2, b / 2, c / 2], r: Math.max(a, b, c) * 0.9, yaw: -0.7, pitch: 0.35 }], ...SEQ(E.map(([i, j]) => ['seg', V[i], V[j], { c: 'b' }]), 200, 40), ...(diag ? [['seg', V[0], V[6], { c: 'y', w: 3, d: 900 }]] : [])]; };
  G('Solids/Cube and box', 'Cube and rectangular box|Cube et pavé droit|Cubo y ortoedro|立方体と直方体|正方体与长方体',
    { s: R`Volume: length × width × height. The space diagonal uses Pythagoras twice — across the base, then up — so $d = \sqrt{a^2 + b^2 + c^2}$; for a cube $a\sqrt3$.|Volume : longueur × largeur × hauteur. La grande diagonale utilise Pythagore deux fois — sur la base puis en hauteur — donc $d = \sqrt{a^2 + b^2 + c^2}$ ; pour un cube $a\sqrt3$.|Volumen: largo × ancho × alto. La diagonal del espacio usa Pitágoras dos veces (en la base y luego en altura): $d = \sqrt{a^2 + b^2 + c^2}$; en un cubo $a\sqrt3$.|体積は縦 × 横 × 高さ。空間対角線は三平方の定理を 2 回（底面→高さ）で $d = \sqrt{a^2 + b^2 + c^2}$、立方体なら $a\sqrt3$。|体积 = 长 × 宽 × 高。体对角线用两次勾股定理（底面再向上）：$d = \sqrt{a^2 + b^2 + c^2}$；正方体为 $a\sqrt3$。`,
      a: [Y(R`V = abc,\quad d = \sqrt{a^2 + b^2 + c^2}`, { s: 26 }), ...BOX(3, 4, 2.5)] },
    { s: R`A box $3 \times 4 \times 12$: $V = 144$ and $d = \sqrt{9 + 16 + 144} = 13$.|Pavé $3 \times 4 \times 12$ : $V = 144$, $d = 13$.|Ortoedro $3 \times 4 \times 12$: $V = 144$, $d = 13$.|$V = 144$、$d = 13$。|$V = 144$，$d = 13$。`,
      a: [F(R`V = 3\cdot 4\cdot 12 = 144`), Y(R`d = \sqrt{9 + 16 + 144} = 13`)] },
    { a: [F(R`\text{cube},\quad d = 6\sqrt3`), ...BOX(3, 3, 3)],
      ex: { k: 'val', v: '216', q: R`A cube has space diagonal $6\sqrt3$. Find its volume.|Un cube a une grande diagonale de $6\sqrt3$. Calculez son volume.|Un cubo tiene diagonal $6\sqrt3$. Halla su volumen.|空間対角線が $6\sqrt3$ の立方体の体積を求めよ。|体对角线为 $6\sqrt3$ 的正方体体积是多少？`, sol: [R`a\sqrt3 = 6\sqrt3 \Rightarrow a = 6`, R`V = 216`] } });

  const CYL = (r, h) => [['3d', { c: [0, 0, h / 2], r: Math.max(r, h) * 1.1, yaw: -0.6, pitch: 0.4 }], ...SEQ([['circ3', [0, 0, 0], [0, 0, 1], r, { c: 'b', fill: 0.15 }], ['circ3', [0, 0, h], [0, 0, 1], r, { c: 'b', fill: 0.15 }], ['seg', [r, 0, 0], [r, 0, h], { c: 'b' }], ['seg', [-r, 0, 0], [-r, 0, h], { c: 'b' }], ['seg', [0, r, 0], [0, r, h], { c: 'b' }], ['seg', [0, -r, 0], [0, -r, h], { c: 'b' }], ['seg', [0, 0, 0], [r, 0, 0], { c: 'y' }], ['seg', [0, 0, 0], [0, 0, h], { c: 'p', dash: true }]], 200, 120)];
  G('Solids/Prism and cylinder', 'Prism and cylinder|Prisme et cylindre|Prisma y cilindro|角柱と円柱|棱柱与圆柱',
    { s: R`A prism or cylinder is a base pushed straight up: stack copies of the base $h$ high, so $V = Bh$. The curved side of a cylinder unrolls into a rectangle $2\pi r$ by $h$; add the two discs for the total area.|Un prisme ou un cylindre est une base « poussée » vers le haut : on empile la base sur une hauteur $h$, d’où $V = Bh$. La surface latérale d’un cylindre se déroule en un rectangle $2\pi r$ sur $h$ ; on ajoute les deux disques pour l’aire totale.|Un prisma o cilindro es una base empujada hacia arriba: apila la base hasta la altura $h$, así que $V = Bh$. La cara curva del cilindro se desenrolla en un rectángulo $2\pi r$ por $h$; suma los dos círculos para el área total.|角柱・円柱は底面をまっすぐ押し上げた形で $V = Bh$。円柱の側面は $2\pi r \times h$ の長方形に開け、2 つの円を足すと表面積。|棱柱或圆柱是底面向上平移形成：$V = Bh$。圆柱侧面展开是 $2\pi r \times h$ 的矩形，加上两个圆得表面积。`,
      a: [Y(R`V = Bh,\quad V = \pi r^2 h,\quad A = 2\pi r(r + h)`, { s: 24 }), ...CYL(1.5, 3)] },
    { s: R`Cylinder $r = 3$, $h = 5$: $V = 45\pi \approx 141.4$ and $A = 2\pi\cdot 3\cdot 8 = 48\pi$.|Cylindre $r = 3$, $h = 5$ : $V = 45\pi$, $A = 48\pi$.|Cilindro $r = 3$, $h = 5$: $V = 45\pi$, $A = 48\pi$.|$45\pi$、$48\pi$。|$45\pi$，$48\pi$。`,
      a: [F(R`V = \pi\cdot 9\cdot 5 = 45\pi`), Y(R`A = 2\pi\cdot 3\cdot(3 + 5) = 48\pi`)] },
    { a: [F(R`r = 2,\quad h = 7`), ...CYL(2, 7)],
      ex: { k: 'val', v: '28pi', q: R`Find the volume of a cylinder with radius 2 and height 7.|Calculez le volume d’un cylindre de rayon 2 et de hauteur 7.|Halla el volumen de un cilindro de radio 2 y altura 7.|半径 2、高さ 7 の円柱の体積を求めよ。|半径 2、高 7 的圆柱体积是多少？`, sol: [R`\pi\cdot 2^2\cdot 7`, R`= 28\pi \approx 87.96`] } });

  const CONE = (r, h) => [['3d', { c: [0, 0, h / 2], r: Math.max(r, h) * 1.1, yaw: -0.6, pitch: 0.4 }], ...SEQ([['circ3', [0, 0, 0], [0, 0, 1], r, { c: 'b', fill: 0.15 }], ['seg', [r, 0, 0], [0, 0, h], { c: 'b' }], ['seg', [-r, 0, 0], [0, 0, h], { c: 'b' }], ['seg', [0, r, 0], [0, 0, h], { c: 'b' }], ['seg', [0, -r, 0], [0, 0, h], { c: 'b' }], ['seg', [0, 0, 0], [0, 0, h], { c: 'p', dash: true }], ['seg', [0, 0, 0], [r, 0, 0], { c: 'y' }], ['lab3', [r * 0.6, 0, h * 0.55], 'l', { c: 'b' }]], 200, 120)];
  G('Solids/Pyramid and cone', 'Pyramid and cone|Pyramide et cône|Pirámide y cono|角錐と円錐|棱锥与圆锥',
    { s: R`A pyramid or cone holds exactly one third of the prism or cylinder with the same base and height (three square pyramids fit into a cube). The lateral surface of a cone unrolls into a sector of radius $l$ (the slant height) and arc $2\pi r$, area $\pi r l$.|Une pyramide ou un cône contient exactement le tiers du prisme ou du cylindre de même base et de même hauteur (trois pyramides remplissent un cube). La surface latérale d’un cône se déroule en un secteur de rayon $l$ (génératrice) et d’arc $2\pi r$, d’aire $\pi r l$.|Una pirámide o cono contiene exactamente un tercio del prisma o cilindro de igual base y altura (tres pirámides llenan un cubo). La superficie lateral del cono se desenrolla en un sector de radio $l$ (generatriz) y arco $2\pi r$, de área $\pi r l$.|角錐・円錐は同じ底面・高さの角柱・円柱のちょうど $\tfrac13$（3 つの四角錐で立方体）。円錐の側面は半径 $l$（母線）、弧 $2\pi r$ の扇形で面積 $\pi r l$。|棱锥或圆锥恰为同底同高棱柱或圆柱的三分之一（三个四棱锥拼成正方体）。圆锥侧面展开是半径为母线 $l$、弧长 $2\pi r$ 的扇形，面积 $\pi r l$。`,
      a: [Y(R`V = \tfrac13 Bh,\quad V = \tfrac13\pi r^2 h,\quad A_{\text{lat}} = \pi r l`, { s: 22 }), ...CONE(1.5, 3)] },
    { s: R`Cone $r = 3$, $h = 4$: slant height $l = 5$, $V = \tfrac13\pi\cdot 9\cdot 4 = 12\pi$, lateral area $15\pi$.|Cône $r = 3$, $h = 4$ : $l = 5$, $V = 12\pi$, aire latérale $15\pi$.|Cono $r = 3$, $h = 4$: $l = 5$, $V = 12\pi$, área lateral $15\pi$.|$V = 12\pi$、側面積 $15\pi$。|$V = 12\pi$，侧面积 $15\pi$。`,
      a: [F(R`l = \sqrt{9 + 16} = 5`), Y(R`V = 12\pi,\quad A_{\text{lat}} = 15\pi`)] },
    { a: [F(R`\text{square base } 6 \times 6,\quad h = 5`)],
      ex: { k: 'val', v: '60', q: R`Find the volume of a pyramid with a $6 \times 6$ square base and height 5.|Calculez le volume d’une pyramide à base carrée $6 \times 6$ et de hauteur 5.|Halla el volumen de una pirámide de base cuadrada $6 \times 6$ y altura 5.|底面が $6 \times 6$ の正方形、高さ 5 の四角錐の体積を求めよ。|底面为 $6 \times 6$ 正方形、高 5 的棱锥体积是多少？`, sol: [R`\tfrac13\cdot 36\cdot 5`, R`= 60`] } });

  G('Solids/Sphere', 'The sphere|La sphère|La esfera|球|球',
    { s: R`Archimedes’ favourite result: a sphere fills two thirds of the cylinder around it, $\tfrac23\cdot\pi r^2\cdot 2r = \tfrac43\pi r^3$, and its surface equals the cylinder’s curved side, $2\pi r\cdot 2r = 4\pi r^2$ — four great circles.|Le résultat préféré d’Archimède : une sphère remplit les deux tiers du cylindre qui l’entoure, $\tfrac43\pi r^3$, et sa surface égale la surface latérale du cylindre, $4\pi r^2$ — quatre grands cercles.|El resultado favorito de Arquímedes: una esfera llena dos tercios del cilindro que la rodea, $\tfrac43\pi r^3$, y su superficie es igual a la cara curva del cilindro, $4\pi r^2$: cuatro círculos máximos.|アルキメデスの結果：球は外接円柱の $\tfrac23$、$\tfrac43\pi r^3$。表面積は円柱の側面積と同じ $4\pi r^2$（大円 4 つ分）。|阿基米德最得意的结果：球占外切圆柱的三分之二，$\tfrac43\pi r^3$；表面积等于圆柱侧面积 $4\pi r^2$——四个大圆。`,
      a: [Y(R`V = \tfrac43\pi r^3,\qquad A = 4\pi r^2`, { s: 28 }), ['3d', { c: [0, 0, 0], r: 2.4, yaw: -0.6, pitch: 0.35 }], ['sph', [0, 0, 0], 1.6, { c: 'y' }], ['seg', [0, 0, 0], [1.6, 0, 0], { c: 'p' }]] },
    { s: R`$r = 3$: $V = \tfrac43\pi\cdot 27 = 36\pi$ and $A = 4\pi\cdot 9 = 36\pi$ — equal numbers, but different units.|$r = 3$ : $V = 36\pi$ et $A = 36\pi$ — mêmes nombres, unités différentes.|$r = 3$: $V = 36\pi$ y $A = 36\pi$: mismos números, unidades distintas.|$36\pi$ と $36\pi$。|$36\pi$ 与 $36\pi$。`,
      a: [Y(R`V = 36\pi,\quad A = 36\pi`)] },
    { a: [F(R`A = 100\pi`)],
      ex: { k: 'val', v: '500pi/3', q: R`A sphere has surface area $100\pi$. Find its volume.|Une sphère a une aire de $100\pi$. Calculez son volume.|Una esfera tiene área $100\pi$. Halla su volumen.|表面積 $100\pi$ の球の体積を求めよ。|表面积为 $100\pi$ 的球体积是多少？`, sol: [R`4\pi r^2 = 100\pi \Rightarrow r = 5`, R`V = \tfrac43\pi\cdot 125 = \frac{500\pi}{3}`] } });

  G('Solids/Euler’s formula', 'Euler’s formula for polyhedra|Relation d’Euler|Fórmula de Euler|オイラーの多面体定理|欧拉公式',
    { s: R`For any convex polyhedron, vertices minus edges plus faces is always 2. It is a quick check when counting, and it lets you find one of $V$, $E$, $F$ from the other two.|Pour tout polyèdre convexe, sommets moins arêtes plus faces vaut toujours 2. C’est une vérification rapide quand on compte, et on peut en déduire l’un de $V$, $E$, $F$ à partir des deux autres.|Para todo poliedro convexo, vértices menos aristas más caras es siempre 2. Sirve para comprobar recuentos y para hallar uno de $V$, $E$, $F$ a partir de los otros dos.|凸多面体では 頂点 − 辺 + 面 = 2 が常に成り立つ。数え間違いの確認や、2 つから残り 1 つを求めるのに使う。|对任意凸多面体，顶点数减棱数加面数恒为 2。可用来检验计数，也可由两个求第三个。`,
      a: [Y(R`V - E + F = 2`, { s: 30 }), ...BOX(2.5, 2.5, 2.5, false)] },
    { s: R`Cube: $8 - 12 + 6 = 2$. Tetrahedron: $4 - 6 + 4 = 2$. Octahedron: $6 - 12 + 8 = 2$.|Cube : $8 - 12 + 6 = 2$. Tétraèdre : $4 - 6 + 4 = 2$. Octaèdre : $6 - 12 + 8 = 2$.|Cubo: $8 - 12 + 6 = 2$. Tetraedro: $4 - 6 + 4 = 2$. Octaedro: $6 - 12 + 8 = 2$.|立方体・四面体・八面体で確認。|正方体、四面体、八面体验证。`,
      a: [F(R`8 - 12 + 6 = 2`), Y(R`4 - 6 + 4 = 2,\quad 6 - 12 + 8 = 2`)] },
    { a: [F(R`\text{icosahedron:}\ F = 20,\ V = 12`)],
      ex: { k: 'val', v: '30', q: R`An icosahedron has 20 faces and 12 vertices. How many edges does it have?|Un icosaèdre a 20 faces et 12 sommets. Combien a-t-il d’arêtes ?|Un icosaedro tiene 20 caras y 12 vértices. ¿Cuántas aristas tiene?|正二十面体は面 20、頂点 12。辺はいくつか。|正二十面体有 20 个面、12 个顶点，有多少条棱？`, sol: [R`12 - E + 20 = 2`, R`E = 30`] } });

  Cheats.tutor('geometry', L);
})();
